    land={**card(616,"Island","Basic Land — Island"),"instance_id":"discard-cycle-land","owner_id":"player","controller_id":"player","tapped":False,"damage":0,"counters":{},"summoning_sick":False};cycler={**card(617,"Discarded Dream","Creature — Illusion","{4}{U}","3","3"),"oracle_text":"Cycling {1}\nWhen you discard this card, you gain 2 life.","instance_id":"discarded-dream","owner_id":"player","controller_id":"player","tapped":False,"damage":0,"counters":{},"summoning_sick":False};player["battlefield"].append(land);player["hand"].append(cycler);before_life=player["life"]
