    mountain={**card(750,"Mountain","Basic Land — Mountain"),"instance_id":"condition-mountain","owner_id":"bot","controller_id":"bot","tapped":False,"damage":0,"counters":{},"summoning_sick":False};bot["battlefield"].append(mountain)
