def test_named_self_replacement_does_not_modify_other_creatures_and_threshold_fires_once():
    state=kept_game();player=next(p for p in state["players"] if p["id"]=="player")
    clock={**card(1430,"Test Clock","Artifact"),"oracle_text":"If one or more charge counters would be put on Test Clock, twice that many charge counters are put on it instead. When the twelfth charge counter is put on this artifact, draw seven cards.","instance_id":"test-clock","owner_id":"player","controller_id":"player","tapped":False,"damage":0,"counters":{"charge":10},"summoning_sick":False}
    other={**card(1431,"Other Battery","Artifact Creature — Construct","","1","1"),"instance_id":"other-battery","owner_id":"player","controller_id":"player","tapped":False,"damage":0,"counters":{},"summoning_sick":False};player["battlefield"].extend([clock,other])
    assert _add_counters(state,other,"charge",1,"player")==1
    assert _add_counters(state,clock,"charge",1,"player")==2 and clock["counters"]["charge"]==12
    assert len(state["stack"])==1


def test_static_counter_prevention_blocks_permanent_and_player_counters():
    state=kept_game();player=next(p for p in state["players"] if p["id"]=="player");bot=next(p for p in state["players"] if p["id"]=="bot")
    solemnity={**card(1440,"Test Solemnity","Enchantment"),"oracle_text":"Players can't get counters. Counters can't be put on artifacts, creatures, enchantments, or lands.","instance_id":"test-solemnity","owner_id":"player","controller_id":"player","tapped":False,"damage":0,"counters":{},"summoning_sick":False}
    creature={**card(1441,"Prevented Creature","Creature — Human","","2","2"),"instance_id":"prevented-creature","owner_id":"bot","controller_id":"bot","tapped":False,"damage":0,"counters":{},"summoning_sick":False};player["battlefield"].append(solemnity);bot["battlefield"].append(creature)
    assert _add_counters(state,creature,"+1/+1",2,"bot")==0 and creature["counters"]=={}
    assert _add_counters(state,bot,"poison",2,"player")==0 and bot["poison"]==0 and not state["stack"]


def test_investigate_creates_usable_clues_and_supports_twice():
    state=kept_game();state=perform_action(state,"player",{"type":"advance_phase"});player=next(p for p in state["players"] if p["id"]=="player")
    for index in range(2):
        land=next(card for card in player["library"] if "Land" in card["type_line"]);player["library"].remove(land);land["instance_id"]=f"clue-land-{index}";land["tapped"]=False;player["battlefield"].append(land)
    spell={**card(1450,"Double Investigation","Sorcery"),"oracle_text":"Investigate twice.","instance_id":"double-investigation","owner_id":"player","controller_id":"player","tapped":False,"damage":0,"counters":{},"summoning_sick":False};player["hand"].append(spell)
    state=perform_action(state,"player",{"type":"cast","card_id":"double-investigation"});state=perform_action(state,"player",{"type":"resolve"});player=next(p for p in state["players"] if p["id"]=="player");clues=[token for token in player["battlefield"] if "Clue" in token["type_line"]]
    assert len(clues)==2 and all(any(action.get("card_id")==clue["instance_id"] for action in legal_actions(state,"player")) for clue in clues)


def test_amass_creates_then_grows_a_typed_army_through_counter_rules():
    state=kept_game();state=perform_action(state,"player",{"type":"advance_phase"});player=next(p for p in state["players"] if p["id"]=="player")
    first={**card(1460,"Raise Orcs","Sorcery"),"oracle_text":"Amass Orcs 2.","instance_id":"raise-orcs","owner_id":"player","controller_id":"player","tapped":False,"damage":0,"counters":{},"summoning_sick":False};second={**card(1461,"Raise Zombies","Sorcery"),"oracle_text":"Amass Zombies 3.","instance_id":"raise-zombies","owner_id":"player","controller_id":"player","tapped":False,"damage":0,"counters":{},"summoning_sick":False};player["hand"].extend([first,second])
    state=perform_action(state,"player",{"type":"cast","card_id":"raise-orcs"});state=perform_action(state,"player",{"type":"resolve"});state=perform_action(state,"player",{"type":"cast","card_id":"raise-zombies"});state=perform_action(state,"player",{"type":"resolve"});player=next(p for p in state["players"] if p["id"]=="player");armies=[token for token in player["battlefield"] if "Army" in token["type_line"]]
    assert len(armies)==1 and armies[0]["counters"]["+1/+1"]==5 and all(subtype in armies[0]["type_line"] for subtype in ("Orc","Zombie","Army"))


def test_multiple_armies_require_a_choice_and_bot_selects_one():
    state=kept_game();player=next(p for p in state["players"] if p["id"]=="player")
    armies=[{**card(1470+index,f"Army {index}","Token Creature — Zombie Army","","0","0"),"instance_id":f"army-{index}","owner_id":"player","controller_id":"player","tapped":False,"damage":0,"counters":{"+1/+1":index+1},"summoning_sick":False,"token":True} for index in range(2)];player["battlefield"].extend(armies)
    _amass(state,player,"Orc",2,"Test Muster");actions=legal_actions(state,"player")
    assert actions[0]["type"]=="choose_amass_army" and {target["id"] for target in actions[0]["targets"]}=={"army-0","army-1"}
    state=perform_action(state,"player",{"type":"choose_amass_army","target_id":"army-1"});player=next(p for p in state["players"] if p["id"]=="player");chosen=next(card for card in player["battlefield"] if card["instance_id"]=="army-1")
    assert chosen["counters"]["+1/+1"]==4 and "Orc" in chosen["type_line"] and state["pending_amass"] is None
    bot=next(p for p in state["players"] if p["id"]=="bot");state["pending_amass"]={"player_id":"bot","source_name":"Bot Muster","subtype":"Goblin","amount":2,"card_ids":[]}
    bot_armies=[{**army,"instance_id":f"bot-{army['instance_id']}","owner_id":"bot","controller_id":"bot"} for army in armies];bot["battlefield"].extend(bot_armies);state["pending_amass"]["card_ids"]=[army["instance_id"] for army in bot_armies];state["priority_player_id"]="bot"
    choice=choose_bot_action(state,"expert");assert choice["type"]=="choose_amass_army" and choice["target_id"]=="bot-army-1"


def test_incubate_creates_countered_transformable_incubator():
    state=kept_game();state=perform_action(state,"player",{"type":"advance_phase"});player=next(p for p in state["players"] if p["id"]=="player");lands=[]
    for index in range(2):
        land=next(card for card in player["library"] if "Land" in card["type_line"]);player["library"].remove(land);land["instance_id"]=f"incubate-land-{index}";land["tapped"]=False;player["battlefield"].append(land);lands.append(land)
    spell={**card(1480,"Prepare New Life","Sorcery"),"oracle_text":"Incubate 3.","instance_id":"prepare-new-life","owner_id":"player","controller_id":"player","tapped":False,"damage":0,"counters":{},"summoning_sick":False};player["hand"].append(spell)
    state=perform_action(state,"player",{"type":"cast","card_id":"prepare-new-life"});state=perform_action(state,"player",{"type":"resolve"});player=next(p for p in state["players"] if p["id"]=="player");token=next(card for card in player["battlefield"] if "Incubator" in card["type_line"]);action=next(action for action in legal_actions(state,"player") if action.get("card_id")==token["instance_id"])
    assert token["counters"]["+1/+1"]==3 and action["type"]=="activate"
    state=perform_action(state,"player",{"type":"activate","card_id":token["instance_id"],"ability_index":action["ability_index"],"cost_card_ids":[]});state=perform_action(state,"player",{"type":"resolve"});player=next(p for p in state["players"] if p["id"]=="player");token=next(card for card in player["battlefield"] if card["instance_id"]==token["instance_id"])
    assert token["current_face"]==1 and "Phyrexian" in token["type_line"] and token["counters"]["+1/+1"]==3


def test_cascade_reveals_in_order_and_casts_strictly_lower_value_spell_for_free():
    state=kept_game();state=perform_action(state,"player",{"type":"advance_phase"});player=next(p for p in state["players"] if p["id"]=="player")
    for index in range(3):
        land=next(card for card in player["library"] if "Land" in card["type_line"]);player["library"].remove(land);land["instance_id"]=f"cascade-land-{index}";land["tapped"]=False;player["battlefield"].append(land)
    cascade={**card(1490,"Testing Blast","Sorcery","{3}"),"oracle_text":"Cascade","keywords":["Cascade"],"mana_value":3,"instance_id":"testing-blast","owner_id":"player","controller_id":"player","tapped":False,"damage":0,"counters":{},"summoning_sick":False};candidate={**card(1491,"Free Bear","Creature — Bear","{1}{G}","2","2"),"mana_value":2,"instance_id":"free-bear","owner_id":"player","controller_id":"player","tapped":False,"damage":0,"counters":{},"summoning_sick":False};revealed_land={**card(1492,"Reveal Forest","Basic Land — Forest"),"mana_value":0,"instance_id":"reveal-forest","owner_id":"player","controller_id":"player","tapped":False,"damage":0,"counters":{},"summoning_sick":False};player["hand"].append(cascade);player["library"].extend([candidate,revealed_land])
    state=perform_action(state,"player",{"type":"cast","card_id":"testing-blast"});assert [item.get("kind","spell") for item in state["stack"]]==["spell","cascade"]
    state=perform_action(state,"player",{"type":"resolve"});actions=legal_actions(state,"player");cast_action=next(action for action in actions if action["type"]=="cast_discovered")
    assert cast_action["card_id"]=="free-bear" and {card["instance_id"] for card in next(p for p in state["players"] if p["id"]=="player")["exile"]}>={"free-bear","reveal-forest"}
    state=perform_action(state,"player",{"type":"cast_discovered"});assert [item["card"]["name"] for item in state["stack"]]==["Testing Blast","Free Bear"]
    state=perform_action(state,"player",{"type":"resolve"});player=next(p for p in state["players"] if p["id"]=="player");assert any(card["instance_id"]=="free-bear" for card in player["battlefield"]) and any(card["instance_id"]=="reveal-forest" for card in player["library"]) and not player["exile"]


def test_discover_allows_equal_value_and_bot_casts_a_targeted_card():
    state=kept_game();state["active_player_id"]="bot";state["priority_player_id"]="bot";state["phase"]="precombat_main";bot=next(p for p in state["players"] if p["id"]=="bot");player=next(p for p in state["players"] if p["id"]=="player")
    target={**card(1500,"Discovery Target","Creature — Giant","","4","4"),"instance_id":"discovery-target","owner_id":"player","controller_id":"player","tapped":False,"damage":0,"counters":{},"summoning_sick":False};found={**card(1501,"Discovered Removal","Sorcery","{2}{B}"),"oracle_text":"Destroy target creature.","mana_value":3,"instance_id":"discovered-removal","owner_id":"bot","controller_id":"bot","tapped":False,"damage":0,"counters":{},"summoning_sick":False};source={**card(1502,"Discovery Effect","Ability"),"oracle_text":"Discover 3.","instance_id":"discovery-effect","owner_id":"bot","controller_id":"bot","tapped":False,"damage":0,"counters":{},"summoning_sick":False};player["battlefield"].append(target);bot["library"].append(found);state["stack"].append({"id":"discover-stack","kind":"ability","card":source,"controller_id":"bot","target_id":None,"source_id":"missing"})
    state=perform_action(state,"bot",{"type":"resolve"});actions=legal_actions(state,"bot");assert {action["type"] for action in actions}>={"cast_discovered","hand_discovered"}
    choice=choose_bot_action(state,"expert");assert choice["type"]=="cast_discovered" and choice["target_id"]=="discovery-target"
    state=perform_action(state,"bot",choice);assert state["stack"][-1]["card"]["instance_id"]=="discovered-removal"


def test_discover_again_trigger_waits_until_the_first_choice_finishes():
    state=kept_game();player=next(p for p in state["players"] if p["id"]=="player")
    watcher={**card(1510,"Discovery Echo","Enchantment"),"oracle_text":"Whenever you discover, discover again for the same value.","instance_id":"discovery-echo","owner_id":"player","controller_id":"player","tapped":False,"damage":0,"counters":{},"summoning_sick":False};first={**card(1511,"First Discovery","Creature — Scout","{3}","3","3"),"mana_value":3,"instance_id":"first-discovery","owner_id":"player","controller_id":"player"};second={**card(1512,"Second Discovery","Creature — Scout","{2}","2","2"),"mana_value":2,"instance_id":"second-discovery","owner_id":"player","controller_id":"player"};source={**card(1513,"Discover Source","Ability"),"oracle_text":"Discover 3.","instance_id":"discover-source","owner_id":"player","controller_id":"player"};player["battlefield"].append(watcher);player["library"].extend([second,first]);state["stack"].append({"id":"discover-source-stack","kind":"ability","card":source,"controller_id":"player","target_id":None,"source_id":"missing"})
    state=perform_action(state,"player",{"type":"resolve"});assert state["pending_discovery"] and not state["stack"]
    state=perform_action(state,"player",{"type":"hand_discovered"});assert not state["pending_discovery"] and state["stack"][-1]["card"]["oracle_text"].casefold().startswith("discover 3")
    state=perform_action(state,"player",{"type":"resolve"});assert state["pending_discovery"] and state["pending_discovery"]["candidate_id"]=="second-discovery"


def test_manifest_creates_an_anonymous_two_two_and_reveals_it_when_it_leaves():
    state=kept_game();player=next(p for p in state["players"] if p["id"]=="player");hidden={**card(1520,"Hidden Dragon","Creature — Dragon","{3}{R}","4","4"),"instance_id":"hidden-dragon","owner_id":"player","controller_id":"player"};source={**card(1521,"Manifest Source","Ability"),"oracle_text":"Manifest the top card of your library.","instance_id":"manifest-source","owner_id":"player","controller_id":"player"};player["library"].append(hidden);state["stack"].append({"id":"manifest-stack","kind":"ability","card":source,"controller_id":"player","target_id":None,"source_id":"missing"})
    state=perform_action(state,"player",{"type":"resolve"});player=next(p for p in state["players"] if p["id"]=="player");manifested=next(card for card in player["battlefield"] if card["instance_id"]=="hidden-dragon")
    assert manifested["face_down"] and manifested["name"]=="Face-Down Creature" and manifested["type_line"]=="Creature" and manifested["power"]==manifested["toughness"]=="2"
    opponent_view=public_state(state,"bot");hidden_view=next(card for owner in opponent_view["players"] if owner["id"]=="player" for card in owner["battlefield"] if card["instance_id"]=="hidden-dragon");assert "face_down_values" not in hidden_view and "Hidden Dragon" not in repr(hidden_view)
    state=perform_action(state,"player",{"type":"move_zone","target_id":"hidden-dragon","destination":"graveyard"});player=next(p for p in state["players"] if p["id"]=="player");revealed=next(card for card in player["graveyard"] if card["instance_id"]=="hidden-dragon");assert revealed["name"]=="Hidden Dragon" and not revealed.get("face_down")


