def test_nonmana_morph_costs_are_parsed_and_reveal_cost_is_enforced():
    examples={"Morph—Reveal a blue card in your hand.":("reveal",1,"blue"),"Morph—Discard a Zombie card.":("discard",1,"zombie"),"Morph—Return two Islands you control to their owner's hand.":("return",2,"island"),"Morph—Sacrifice another creature.":("sacrifice",1,"creature"),"Morph—Pay 5 life.":("life",5,None)}
