    cast=next(entry for entry in legal_actions(state,"player") if entry.get("card_id")=="highway-robbery" and entry["type"]=="cast");assert cast["source"]=="plot" and "without paying" in cast["label"]
    state=perform_action(state,"player",{"type":"cast","card_id":"highway-robbery","source":"plot"});player=next(p for p in state["players"] if p["id"]=="player");assert not any(card["tapped"] for card in player["battlefield"]);assert state["stack"][-1]["cast_source_zone"]=="exile"


