def test_titan_is_sacrificed_after_normal_cast_but_remains_after_escape():
    def titan_state(escaped:bool):
        state=kept_game();state["phase"]="precombat_main";player=next(p for p in state["players"] if p["id"]=="player");titan={**card(1940,"Kroxa, Titan of Death's Hunger","Legendary Creature — Elder Giant","{B}{R}","6","6"),"oracle_text":"When Kroxa enters, sacrifice it unless it escaped.\nEscape—{B}{B}{R}{R}, Exile five other cards from your graveyard.","instance_id":"kroxa","owner_id":"player","controller_id":"player"};state["stack"]=[{"id":"kroxa-stack","kind":"spell","card":titan,"controller_id":"player","escaped":escaped,"escape_counters":0,"cast_source_zone":"graveyard" if escaped else "hand","target_ids":[],"mode_indices":[],"mode_targets":[]}];return state
    state=titan_state(False);state=perform_action(state,"player",{"type":"resolve"});assert state["stack"] and any(card["instance_id"]=="kroxa" for card in next(p for p in state["players"] if p["id"]=="player")["battlefield"]);state=perform_action(state,"player",{"type":"resolve"});assert any(card["instance_id"]=="kroxa" for card in next(p for p in state["players"] if p["id"]=="player")["graveyard"])
    state=titan_state(True);state=perform_action(state,"player",{"type":"resolve"});state=perform_action(state,"player",{"type":"resolve"});assert any(card["instance_id"]=="kroxa" for card in next(p for p in state["players"] if p["id"]=="player")["battlefield"])


