def test_storm_copies_a_spell_once_for_each_spell_cast_before_it():
    state=kept_game();state["phase"]="precombat_main";player=next(p for p in state["players"] if p["id"]=="player");player["cast_event_turn"]=state["turn"];player["spells_cast_this_turn"]=2;lands=[{**card(2320+index,"Forest","Basic Land — Forest"),"instance_id":f"storm-land-{index}","owner_id":"player","controller_id":"player","tapped":False,"damage":0,"counters":{},"summoning_sick":False} for index in range(2)];storm={**card(2322,"Weather the Storm","Instant","{1}{G}"),"oracle_text":"You gain 3 life.\nStorm (When you cast this spell, copy it for each spell cast before it this turn.)","keywords":["Storm"],"instance_id":"weather-storm","owner_id":"player","controller_id":"player"};player["battlefield"]=lands;player["hand"]=[storm];life=player["life"]
    state=perform_action(state,"player",{"type":"cast","card_id":"weather-storm"});assert state["stack"][-1]["kind"]=="storm_trigger" and state["stack"][-1]["storm_count"]==2 and next(p for p in state["players"] if p["id"]=="player")["spells_cast_this_turn"]==3
    state=perform_action(state,"player",{"type":"resolve"});assert sum(item.get("kind")=="storm_copy" for item in state["stack"])==2
    while state["stack"]:state=perform_action(state,"player",{"type":"resolve"})
    player=next(p for p in state["players"] if p["id"]=="player");assert player["life"]==life+9 and sum(card["instance_id"]=="weather-storm" for card in player["graveyard"])==1 and player["spells_cast_this_turn"]==3


