def test_bushido_and_flanking_trigger_on_blocks_and_flanking_blockers_are_immune():
    state=kept_game();state["phase"]="combat";player=next(p for p in state["players"] if p["id"]=="player");bot=next(p for p in state["players"] if p["id"]=="bot");attacker={**card(2370,"Samurai Lancer","Creature — Human Samurai","","2","2"),"oracle_text":"Bushido 2 (Whenever this creature blocks or becomes blocked, it gets +2/+2 until end of turn.)\nFlanking (Whenever a creature without flanking blocks this creature, the blocking creature gets -1/-1 until end of turn.)","keywords":["Bushido","Flanking"],"instance_id":"samurai-lancer","owner_id":"player","controller_id":"player","tapped":False,"damage":0,"counters":{},"summoning_sick":False};blocker={**card(2371,"Blocking Samurai","Creature — Human Samurai","","2","2"),"oracle_text":"Bushido 1 (Whenever this creature blocks or becomes blocked, it gets +1/+1 until end of turn.)","keywords":["Bushido"],"instance_id":"blocking-samurai","owner_id":"bot","controller_id":"bot","tapped":False,"damage":0,"counters":{},"summoning_sick":False};player["battlefield"]=[attacker];bot["battlefield"]=[blocker];state=perform_action(state,"player",{"type":"declare_attackers","attacker_ids":["samurai-lancer"]});state=perform_action(state,"bot",{"type":"declare_blockers","blocks":{"blocking-samurai":"samurai-lancer"}});assert sorted(item.get("keyword") for item in state["stack"] if item.get("kind")=="combat_stat_trigger")==["bushido","bushido","flanking"]
    while state["stack"]:state=perform_action(state,state["priority_player_id"],{"type":"resolve"})
    player=next(p for p in state["players"] if p["id"]=="player");bot=next(p for p in state["players"] if p["id"]=="bot");attacker=next(card for card in player["battlefield"] if card["instance_id"]=="samurai-lancer");blocker=next(card for card in bot["battlefield"] if card["instance_id"]=="blocking-samurai");assert (attacker["temporary_power"],attacker["temporary_toughness"])==(2,2) and (blocker["temporary_power"],blocker["temporary_toughness"])==(0,0)
    state=kept_game();state["phase"]="combat";player=next(p for p in state["players"] if p["id"]=="player");bot=next(p for p in state["players"] if p["id"]=="bot");attacker={**attacker,"temporary_power":0,"temporary_toughness":0,"tapped":False};flanker={**blocker,"instance_id":"flanking-blocker","oracle_text":"Flanking","keywords":["Flanking"]};player["battlefield"]=[attacker];bot["battlefield"]=[flanker];state=perform_action(state,"player",{"type":"declare_attackers","attacker_ids":["samurai-lancer"]});state=perform_action(state,"bot",{"type":"declare_blockers","blocks":{"flanking-blocker":"samurai-lancer"}});assert not any(item.get("keyword")=="flanking" for item in state["stack"])


