def test_soulshift_offers_only_spirits_within_its_mana_value_limit_and_returns_the_choice():
    state=kept_game();player=next(p for p in state["players"] if p["id"]=="player");source={**card(2400,"Burr Grafter","Creature — Spirit","","2","2"),"oracle_text":"Soulshift 3 (When this creature dies, you may return target Spirit card with mana value 3 or less from your graveyard to your hand.)","keywords":["Soulshift"],"mana_value":4,"instance_id":"burr-grafter","owner_id":"player","controller_id":"player","tapped":False,"damage":0,"counters":{},"summoning_sick":False};eligible={**card(2401,"Eligible Kami","Creature — Spirit","{2}{G}","2","2"),"mana_value":3,"instance_id":"eligible-kami","owner_id":"player","controller_id":"player"};expensive={**card(2402,"Expensive Kami","Creature — Spirit","{3}{G}","3","3"),"mana_value":4,"instance_id":"expensive-kami","owner_id":"player","controller_id":"player"};outsider={**card(2403,"Cheap Elf","Creature — Elf","{G}","1","1"),"mana_value":1,"instance_id":"cheap-elf","owner_id":"player","controller_id":"player"};player["battlefield"].append(source);player["graveyard"]=[eligible,expensive,outsider];_leave_battlefield(state,player,source,"graveyard");actions=legal_actions(state,"player");choice=next(action for action in actions if action["type"]=="choose_trigger_target");assert {target["id"] for target in choice["targets"]}=={"eligible-kami"} and any(action["type"]=="skip_trigger" for action in actions)
    state=perform_action(state,"player",{"type":"choose_trigger_target","target_id":"eligible-kami"});state=perform_action(state,"player",{"type":"resolve"});player=next(p for p in state["players"] if p["id"]=="player");assert any(card["instance_id"]=="eligible-kami" for card in player["hand"]) and not any(card["instance_id"]=="eligible-kami" for card in player["graveyard"])


