def test_turntimber_basilisk_requires_its_chosen_creature_to_block_if_able():
    state=kept_game();player=next(p for p in state["players"] if p["id"]=="player");bot=next(p for p in state["players"] if p["id"]=="bot");basilisk={**card(2960,"Turntimber Basilisk","Creature — Basilisk","{1}{G}{G}","2","1"),"oracle_text":"Deathtouch\nLandfall — Whenever a land you control enters, you may have target creature block this creature this turn if able.","instance_id":"turntimber-basilisk","owner_id":"player","controller_id":"player","tapped":False,"damage":0,"counters":{},"summoning_sick":False};victim={**card(2961,"Forced Blocker","Creature — Soldier","","2","2"),"instance_id":"forced-blocker","owner_id":"bot","controller_id":"bot","tapped":False,"damage":0,"counters":{},"summoning_sick":False};other={**card(2962,"Free Blocker","Creature — Soldier","","1","1"),"instance_id":"free-blocker","owner_id":"bot","controller_id":"bot","tapped":False,"damage":0,"counters":{},"summoning_sick":False};player["battlefield"]=[basilisk];bot["battlefield"]=[victim,other];land={**card(2963,"Turntimber Forest","Basic Land — Forest"),"instance_id":"turntimber-forest","owner_id":"player","controller_id":"player","tapped":False,"damage":0,"counters":{},"summoning_sick":False};_enter_battlefield(state,player,[land]);actions=legal_actions(state,"player");assert any(action["type"]=="skip_trigger" for action in actions);state=perform_action(state,"player",{"type":"choose_trigger_target","target_id":"forced-blocker"});state=perform_action(state,"player",{"type":"resolve"});bot=next(p for p in state["players"] if p["id"]=="bot");assert bot["battlefield"][0]["must_block_source_ids"]==["turntimber-basilisk"]
    state["phase"]="combat";state["priority_player_id"]="player";state=perform_action(state,"player",{"type":"declare_attackers","attacker_ids":["turntimber-basilisk"],"attack_targets":{"turntimber-basilisk":"bot"}});action=next(action for action in legal_actions(state,"bot") if action["type"]=="declare_blockers");assert action["required_blocks"]=={"forced-blocker":["turntimber-basilisk"]} and not any(action["type"]=="advance_phase" for action in legal_actions(state,"bot"))
    with pytest.raises(RuleViolation):perform_action(state,"bot",{"type":"declare_blockers","blocks":{}})
    state=perform_action(state,"bot",{"type":"declare_blockers","blocks":{"forced-blocker":"turntimber-basilisk"}});assert state["combat"]["blocks"]=={"forced-blocker":"turntimber-basilisk"}


