    state=perform_action(state,"player",{"type":"declare_attackers","attacker_ids":["moraug-ally"],"attack_targets":{"moraug-ally":"bot"}});player=next(p for p in state["players"] if p["id"]=="player");ally=next(card for card in player["battlefield"] if card["instance_id"]=="moraug-ally");assert _parse_stats(ally,state)==(4,2);_advance_turn_phase(state);player=next(p for p in state["players"] if p["id"]=="player");ally=next(card for card in player["battlefield"] if card["instance_id"]=="moraug-ally");assert state["phase"]=="combat" and ally["tapped"] and not state.get("additional_combat_active") and not state.get("additional_combats_pending")


