@pytest.mark.parametrize("pay",[True,False])
def test_springheart_nantuko_landfall_copies_enchanted_creature_or_makes_insect(pay):
    state=kept_game();player=next(p for p in state["players"] if p["id"]=="player");lands=[{**card(3030+index,f"Nantuko Forest {index}","Basic Land — Forest"),"instance_id":f"nantuko-forest-{index}","owner_id":"player","controller_id":"player","tapped":False,"damage":0,"counters":{},"summoning_sick":False} for index in range(2)];bear={**card(3032,"Copied Bear","Creature — Bear","","4","4"),"instance_id":"copied-bear","owner_id":"player","controller_id":"player","tapped":False,"damage":0,"counters":{},"summoning_sick":False};nantuko={**card(3033,"Springheart Nantuko","Enchantment — Aura","{1}{G}","1","1"),"oracle_text":"Bestow {1}{G}\nEnchanted creature gets +1/+1.\nLandfall — Whenever a land you control enters, you may pay {1}{G} if this permanent is attached to a creature you control. If you do, create a token that's a copy of that creature. If you didn't create a token this way, create a 1/1 green Insect creature token.","instance_id":"springheart-attached","owner_id":"player","controller_id":"player","attached_to":"copied-bear","bestowed":True,"bestow_original_type_line":"Enchantment Creature — Insect Monk","tapped":False,"damage":0,"counters":{},"summoning_sick":False};player["battlefield"]=[*lands,bear,nantuko]
    entering={**card(3034,"Nantuko Landfall","Basic Land — Forest"),"instance_id":"nantuko-landfall","owner_id":"player","controller_id":"player","tapped":False,"damage":0,"counters":{},"summoning_sick":False};_enter_battlefield(state,player,[entering]);state=perform_action(state,"player",{"type":"accept_trigger"});state=perform_action(state,"player",{"type":"resolve"});assert any(action["type"]==("pay_optional_mana" if pay else "decline_optional_mana") for action in legal_actions(state,"player"))
    state=perform_action(state,"player",{"type":"pay_optional_mana" if pay else "decline_optional_mana"});player=next(p for p in state["players"] if p["id"]=="player");tokens=[card for card in player["battlefield"] if card.get("token")];assert len(tokens)==1
    if pay:assert tokens[0]["name"]=="Copied Bear" and _parse_stats(tokens[0],state)==(4,4)
    else:assert tokens[0]["name"]=="Insect Token" and _parse_stats(tokens[0],state)==(1,1)


