def test_multikicker_combines_with_x_and_adds_one_distinct_target_per_kick():
    state=kept_game();state=perform_action(state,"player",{"type":"advance_phase"});player=next(p for p in state["players"] if p["id"]=="player");bot=next(p for p in state["players"] if p["id"]=="bot");player["battlefield"]=[{**card(3060+index,f"Storm Mountain {index}","Basic Land — Mountain"),"instance_id":f"storm-mountain-{index}","owner_id":"player","controller_id":"player","tapped":False,"damage":0,"counters":{},"summoning_sick":False} for index in range(8)];victims=[{**card(3070+index,f"Storm Victim {index}","Creature — Bear","","5","5"),"instance_id":f"storm-victim-{index}","owner_id":"bot","controller_id":"bot","tapped":False,"damage":0,"counters":{},"summoning_sick":False} for index in range(2)];bot["battlefield"]=victims
    storm={**card(3072,"Comet Storm","Instant","{X}{R}{R}"),"oracle_text":"Multikicker {1} (You may pay an additional {1} any number of times as you cast this spell.)\nChoose any target, then choose another target for each time this spell was kicked. Comet Storm deals X damage to each of them.","instance_id":"comet-storm","owner_id":"player","controller_id":"player","tapped":False,"damage":0,"counters":{},"summoning_sick":False};player["hand"].append(storm)
    action=next(action for action in legal_actions(state,"player") if action.get("card_id")=="comet-storm" and action.get("multikicker_count")==2);assert action["x_max"]==4 and len(action["target_steps"])==3
    state=perform_action(state,"player",{**action,"x_value":3,"target_ids":["bot","storm-victim-0","storm-victim-1"]});assert state["stack"][-1]["target_ids"]==["bot","storm-victim-0","storm-victim-1"];state=perform_action(state,"player",{"type":"resolve"});bot=next(p for p in state["players"] if p["id"]=="bot");assert bot["life"]==17 and all(creature["damage"]==3 for creature in bot["battlefield"]),state["log"][-5:]


@pytest.mark.parametrize(("name","oracle","expected"),[("Lightkeeper of Emeria","Flying\nWhen this creature enters, you gain 2 life for each time it was kicked.",4),("Wolfbriar Elemental","When this creature enters, create a 2/2 green Wolf creature token for each time it was kicked.",2)])
def test_multikicker_scales_common_enter_effects(name,oracle,expected):
    state=kept_game();state=perform_action(state,"player",{"type":"advance_phase"});player=next(p for p in state["players"] if p["id"]=="player");player["battlefield"]=[{**card(3080+index,f"Scale Land {index}","Basic Land — Forest"),"instance_id":f"scale-land-{index}","owner_id":"player","controller_id":"player","tapped":False,"damage":0,"counters":{},"summoning_sick":False} for index in range(8)];spell={**card(3090,name,"Creature — Elemental","{2}{G}{G}","4","4"),"oracle_text":f"Multikicker {{G}} (You may pay an additional {{G}} any number of times as you cast this spell.)\n{oracle}","instance_id":"scaled-multikicker","owner_id":"player","controller_id":"player","tapped":False,"damage":0,"counters":{},"summoning_sick":False};player["hand"].append(spell);life=player["life"]
    action=next(action for action in legal_actions(state,"player") if action.get("card_id")=="scaled-multikicker" and action.get("multikicker_count")==2);state=perform_action(state,"player",action);state=perform_action(state,"player",{"type":"resolve"});state=perform_action(state,"player",{"type":"resolve"});player=next(p for p in state["players"] if p["id"]=="player")
    if name.startswith("Lightkeeper"):assert player["life"]==life+expected
    else:assert len([card for card in player["battlefield"] if card.get("token") and "Wolf" in card["type_line"]])==expected


def test_multikicker_scales_targeted_damage_and_charge_counters():
    state=kept_game();state=perform_action(state,"player",{"type":"advance_phase"});player=next(p for p in state["players"] if p["id"]=="player");player["battlefield"]=[{**card(3100+index,f"Damage Mountain {index}","Basic Land — Mountain"),"instance_id":f"damage-mountain-{index}","owner_id":"player","controller_id":"player","tapped":False,"damage":0,"counters":{},"summoning_sick":False} for index in range(7)];shaman={**card(3107,"Deathforge Shaman","Creature — Ogre Shaman","{4}{R}","4","3"),"oracle_text":"Multikicker {R} (You may pay an additional {R} any number of times as you cast this spell.)\nWhen this creature enters, it deals damage to target player or planeswalker equal to twice the number of times it was kicked.","instance_id":"deathforge-shaman","owner_id":"player","controller_id":"player","tapped":False,"damage":0,"counters":{},"summoning_sick":False};player["hand"].append(shaman)
    action=next(action for action in legal_actions(state,"player") if action.get("card_id")=="deathforge-shaman" and action.get("multikicker_count")==2);state=perform_action(state,"player",action);state=perform_action(state,"player",{"type":"resolve"});choice=next(action for action in legal_actions(state,"player") if action["type"]=="choose_trigger_target");assert "bot" in {target["id"] for target in choice["targets"]};state=perform_action(state,"player",{"type":"choose_trigger_target","target_id":"bot"});state=perform_action(state,"player",{"type":"resolve"});assert next(p for p in state["players"] if p["id"]=="bot")["life"]==16
    state=kept_game();state=perform_action(state,"player",{"type":"advance_phase"});player=next(p for p in state["players"] if p["id"]=="player");player["battlefield"]=[{**card(3110+index,f"Chalice Land {index}","Basic Land — Wastes"),"instance_id":f"chalice-land-{index}","owner_id":"player","controller_id":"player","tapped":False,"damage":0,"counters":{},"summoning_sick":False} for index in range(6)];chalice={**card(3116,"Everflowing Chalice","Artifact","{0}"),"oracle_text":"Multikicker {2} (You may pay an additional {2} any number of times as you cast this spell.)\nThis artifact enters with a charge counter on it for each time it was kicked.\n{T}: Add {C} for each charge counter on this artifact.","instance_id":"everflowing-chalice","owner_id":"player","controller_id":"player","tapped":False,"damage":0,"counters":{},"summoning_sick":False};player["hand"].append(chalice);action=next(action for action in legal_actions(state,"player") if action.get("card_id")=="everflowing-chalice" and action.get("multikicker_count")==3);state=perform_action(state,"player",action);state=perform_action(state,"player",{"type":"resolve"});chalice=next(card for card in next(p for p in state["players"] if p["id"]=="player")["battlefield"] if card["instance_id"]=="everflowing-chalice");assert chalice["counters"]["charge"]==3


def test_multikicker_up_to_target_trigger_can_finish_before_the_maximum():
    state=kept_game();state=perform_action(state,"player",{"type":"advance_phase"});player=next(p for p in state["players"] if p["id"]=="player");player["battlefield"]=[{**card(3120+index,f"Batroc Mountain {index}","Basic Land — Mountain"),"instance_id":f"batroc-mountain-{index}","owner_id":"player","controller_id":"player","tapped":False,"damage":0,"counters":{},"summoning_sick":False} for index in range(6)];batroc={**card(3126,"Batroc the Leaper","Legendary Creature — Human Villain","{1}{R}","2","2"),"oracle_text":"Multikicker {2} (You may pay an additional {2} any number of times as you cast this spell.)\nBatroc enters with a +1/+1 counter on him for each time he was kicked.\nWhen Batroc enters, he deals damage equal to his power to each of up to X targets, where X is the number of times he was kicked.","instance_id":"batroc","owner_id":"player","controller_id":"player","tapped":False,"damage":0,"counters":{},"summoning_sick":False};player["hand"].append(batroc);action=next(action for action in legal_actions(state,"player") if action.get("card_id")=="batroc" and action.get("multikicker_count")==2);state=perform_action(state,"player",action);state=perform_action(state,"player",{"type":"resolve"});choices=[action for action in legal_actions(state,"player") if action["type"]=="choose_trigger_targets"];assert choices,(state.get("pending_trigger_targets"),state["stack"],state["log"][-5:]);choice=choices[0];assert choice["min_targets"]==0 and len(choice["target_steps"])==2
    state=perform_action(state,"player",{"type":"choose_trigger_targets","target_ids":["bot"]});state=perform_action(state,"player",{"type":"resolve"});assert next(p for p in state["players"] if p["id"]=="bot")["life"]==16


def test_multikicker_up_to_target_trigger_selects_graveyard_cards():
    state=kept_game();state=perform_action(state,"player",{"type":"advance_phase"});player=next(p for p in state["players"] if p["id"]=="player");player["battlefield"]=[{**card(3130+index,f"Anthem Plains {index}","Basic Land — Plains"),"instance_id":f"anthem-plains-{index}","owner_id":"player","controller_id":"player","tapped":False,"damage":0,"counters":{},"summoning_sick":False} for index in range(8)];dead=[{**card(3140+index,f"Anthem Dead {index}","Creature — Soldier","","2","2"),"instance_id":f"anthem-dead-{index}","owner_id":"player","controller_id":"player","tapped":False,"damage":0,"counters":{},"summoning_sick":False} for index in range(2)];player["graveyard"]=dead;anthem={**card(3142,"Marshal's Anthem","Enchantment","{2}{W}{W}"),"oracle_text":"Multikicker {1}{W} (You may pay an additional {1}{W} any number of times as you cast this spell.)\nCreatures you control get +1/+1.\nWhen this enchantment enters, return up to X target creature cards from your graveyard to the battlefield, where X is the number of times this enchantment was kicked.","instance_id":"marshals-anthem","owner_id":"player","controller_id":"player","tapped":False,"damage":0,"counters":{},"summoning_sick":False};player["hand"].append(anthem);action=next(action for action in legal_actions(state,"player") if action.get("card_id")=="marshals-anthem" and action.get("multikicker_count")==2);state=perform_action(state,"player",action);state=perform_action(state,"player",{"type":"resolve"});choice=next(action for action in legal_actions(state,"player") if action["type"]=="choose_trigger_targets");assert {target["id"] for target in choice["target_steps"][0]["targets"]}=={"anthem-dead-0","anthem-dead-1"}
    state=perform_action(state,"player",{"type":"choose_trigger_targets","target_ids":["anthem-dead-1"]});state=perform_action(state,"player",{"type":"resolve"});player=next(p for p in state["players"] if p["id"]=="player");assert any(card["instance_id"]=="anthem-dead-1" for card in player["battlefield"]) and any(card["instance_id"]=="anthem-dead-0" for card in player["graveyard"])


