    chalice={**card(3150,"Everflowing Chalice","Artifact","{0}"),"oracle_text":"Multikicker {2}\nThis artifact enters with a charge counter on it for each time it was kicked.\n{T}: Add {C} for each charge counter on this artifact.","instance_id":"chalice","owner_id":"player","controller_id":"player","tapped":False,"damage":0,"counters":{"charge":3},"summoning_sick":False}
