def test_multikicker_zethi_exiles_selected_instants_with_linked_kick_counters():
    state=kept_game();player=next(p for p in state["players"] if p["id"]=="player");instants=[{**card(3161+index,f"Zethi Instant {index}","Instant","{U}"),"instance_id":f"zethi-instant-{index}","owner_id":"player","controller_id":"player","counters":{}} for index in range(2)];player["graveyard"]=instants;zethi={**card(3163,"Zethi, Arcane Blademaster","Legendary Creature — Human Monk","{3}{U}","3","3"),"oracle_text":"Multikicker {W/U}\nWhen Zethi, Arcane Blademaster enters, exile up to X target instant cards from your graveyard, where X is the number of times Zethi was kicked. Put a kick counter on each of them.\nWhenever Zethi attacks, copy each exiled card you own with a kick counter on it. You may cast the copies.","instance_id":"zethi","owner_id":"player","controller_id":"player","tapped":False,"damage":0,"counters":{},"times_kicked":2,"summoning_sick":False};player["battlefield"]=[zethi];_queue_triggers(state,"enters",zethi,player,sources_override=[(player,zethi)]);choice=next(action for action in legal_actions(state,"player") if action["type"]=="choose_trigger_targets");state=perform_action(state,"player",{"type":"choose_trigger_targets","target_ids":["zethi-instant-1"]});state=perform_action(state,"player",{"type":"resolve"});player=next(p for p in state["players"] if p["id"]=="player");exiled=next(card for card in player["exile"] if card["instance_id"]=="zethi-instant-1");assert exiled["counters"]["kick"]==1 and exiled["zethi_source_id"]=="zethi" and [card["instance_id"] for card in player["graveyard"]]==["zethi-instant-0"]


def test_multikicker_zethi_attack_offers_and_casts_targeted_copies_sequentially():
    state=kept_game();player=next(p for p in state["players"] if p["id"]=="player");zethi={**card(3170,"Zethi, Arcane Blademaster","Legendary Creature — Human Monk","{3}{U}","3","3"),"oracle_text":"Whenever Zethi attacks, copy each exiled card you own with a kick counter on it. You may cast the copies.","instance_id":"zethi","owner_id":"player","controller_id":"player","tapped":True,"damage":0,"counters":{},"summoning_sick":False};first={**card(3171,"Copied Bolt","Instant","{2}{R}"),"oracle_text":"Copied Bolt deals 3 damage to any target.","instance_id":"zethi-bolt","owner_id":"player","controller_id":"player","counters":{"kick":1},"zethi_source_id":"zethi"};second={**card(3172,"Copied Insight","Instant","{2}{U}"),"oracle_text":"Draw two cards.","instance_id":"zethi-draw","owner_id":"player","controller_id":"player","counters":{"kick":1},"zethi_source_id":"zethi"};player["battlefield"]=[zethi];player["exile"]=[first,second];state["combat"]["attackers"]=["zethi"];_queue_triggers(state,"attackers_declared",None,player,sources_override=[(player,zethi)]);state=perform_action(state,"player",{"type":"resolve"});actions=legal_actions(state,"player");cast=next(action for action in actions if action["type"]=="cast_zethi_copy");assert cast["card_id"]=="zethi-bolt" and "bot" in {target["id"] for target in cast["targets"]};state=perform_action(state,"player",{"type":"cast_zethi_copy","target_id":"bot"});assert next(action for action in legal_actions(state,"player") if action["type"]=="cast_zethi_copy")["card_id"]=="zethi-draw";state=perform_action(state,"player",{"type":"decline_zethi_copy"});assert state["pending_zethi_copies"] is None and state["stack"][-1]["kind"]=="zethi_copy";state=perform_action(state,"player",{"type":"resolve"});assert next(p for p in state["players"] if p["id"]=="bot")["life"]==17 and [card["instance_id"] for card in next(p for p in state["players"] if p["id"]=="player")["exile"]]==["zethi-bolt","zethi-draw"]


def test_multikicker_spell_contortion_draws_then_asks_spell_controller_to_pay():
    state=kept_game();player=next(p for p in state["players"] if p["id"]=="player");bot=next(p for p in state["players"] if p["id"]=="bot");bot["battlefield"]=[{**card(3180+index,"Payment Island","Basic Land — Island"),"instance_id":f"payment-island-{index}","owner_id":"bot","controller_id":"bot","tapped":False,"damage":0,"counters":{},"summoning_sick":False} for index in range(2)];enemy={**card(3182,"Enemy Spell","Sorcery","{1}"),"instance_id":"enemy-spell","owner_id":"bot","controller_id":"bot"};contortion={**card(3183,"Spell Contortion","Instant","{2}{U}"),"oracle_text":"Multikicker {1}{U}\nCounter target spell unless its controller pays {2}. Draw a card for each time this spell was kicked.","instance_id":"spell-contortion","owner_id":"player","controller_id":"player"};before=len(player["library"]);state["stack"]=[{"id":"enemy-stack","card":enemy,"controller_id":"bot","target_id":None},{"id":"contortion-stack","card":contortion,"controller_id":"player","target_id":"enemy-stack","multikicker_count":2}];state=perform_action(state,"player",{"type":"resolve"});assert len(next(p for p in state["players"] if p["id"]=="player")["library"])==before-2 and {action["type"] for action in legal_actions(state,"bot")}>={"pay_counter_payment","decline_counter_payment"};state=perform_action(state,"bot",{"type":"decline_counter_payment"});assert not state["stack"] and any(card["instance_id"]=="enemy-spell" for card in next(p for p in state["players"] if p["id"]=="bot")["graveyard"])


def test_start_your_engines_progresses_once_each_turn_and_unlocks_max_speed_rules():
    state=kept_game();player=next(p for p in state["players"] if p["id"]=="player");bot=next(p for p in state["players"] if p["id"]=="bot");engine={**card(3190,"Burnout Bashtronaut","Creature — Goblin","{2}{R}","2","2"),"oracle_text":"Menace\nStart your engines!\nMax speed — This creature has double strike.","keywords":["Menace","Start your engines!","Double strike"],"instance_id":"bashtronaut","owner_id":"player","controller_id":"player","tapped":False,"damage":0,"counters":{},"summoning_sick":False};_enter_battlefield(state,player,[engine]);assert player["speed"]==1 and not _has_keyword(engine,"Double strike")
    def lose_life(current,turn):
        current["turn"]=turn;current["active_player_id"]="player";current["priority_player_id"]="player";bolt={**card(3191+turn,f"Speed Bolt {turn}","Instant","{R}"),"oracle_text":"Speed Bolt deals 1 damage to target player.","instance_id":f"speed-bolt-{turn}","owner_id":"player","controller_id":"player"};current["stack"]=[{"id":f"speed-stack-{turn}","card":bolt,"controller_id":"player","target_id":"bot"}];return perform_action(current,"player",{"type":"resolve"})
    state=lose_life(state,1);assert next(p for p in state["players"] if p["id"]=="player")["speed"]==2;state=lose_life(state,1);assert next(p for p in state["players"] if p["id"]=="player")["speed"]==2;state=lose_life(state,2);state=lose_life(state,3);player=next(p for p in state["players"] if p["id"]=="player");engine=next(card for card in player["battlefield"] if card["instance_id"]=="bashtronaut");assert player["speed"]==4 and _has_keyword(engine,"Double strike")


def test_speed_characteristic_stats_and_hazoret_combat_gate():
    state=kept_game();player=next(p for p in state["players"] if p["id"]=="player");player["speed"]=3;gomif={**card(3200,"Gomif, Fast Racer","Legendary Creature — Goblin Pilot","{2}{R}","*","3"),"oracle_text":"Gomif's power is equal to your speed.\nYour speed can increase beyond 4.","instance_id":"gomif","owner_id":"player","controller_id":"player","tapped":False,"damage":0,"counters":{},"controller_speed":3,"summoning_sick":False};hazoret={**card(3201,"Hazoret, Godseeker","Legendary Creature — God","{3}{R}","5","4"),"oracle_text":"Indestructible, haste\nHazoret can't attack or block unless you have max speed.","instance_id":"hazoret","owner_id":"player","controller_id":"player","tapped":False,"damage":0,"counters":{},"controller_speed":3,"summoning_sick":False};player["battlefield"]=[gomif,hazoret];state["phase"]="combat";assert _parse_stats(gomif,state)==(3,3) and "hazoret" not in next(action for action in legal_actions(state,"player") if action["type"]=="declare_attackers")["card_ids"];player["speed"]=4;hazoret["controller_speed"]=4;assert "hazoret" in next(action for action in legal_actions(state,"player") if action["type"]=="declare_attackers")["card_ids"]


def test_max_speed_unlocks_mana_abilities_and_triggered_abilities():
    catalyzer={**card(3210,"Endrider Catalyzer","Creature — Human Artificer","{2}{R}","2","2"),"oracle_text":"Start your engines!\nMax speed — {T}: Add {R}{R}.","instance_id":"catalyzer","owner_id":"player","controller_id":"player","tapped":False,"damage":0,"counters":{},"controller_speed":3,"summoning_sick":False};assert not _mana_source_options(catalyzer);catalyzer["controller_speed"]=4;assert {option["pool"] for option in _mana_source_options(catalyzer)}=={(0,0,0,2,0,0)}
