def test_threshold_mass_replacements_sacrifice_return_and_damage_the_correct_objects():
    def threshold_state():
        state=kept_game();player=next(p for p in state["players"] if p["id"]=="player");player["graveyard"]=[{**card(3760+index,f"Mass Grave {index}","Sorcery"),"instance_id":f"mass-grave-{index}","owner_id":"player","controller_id":"player"} for index in range(7)];return state,player,next(p for p in state["players"] if p["id"]=="bot")
    def permanent(index,name,type_line,owner,power=None,toughness=None):return {**card(index,name,type_line,"",power,toughness),"instance_id":name.casefold().replace(" ","-"),"owner_id":owner,"controller_id":owner,"tapped":False,"damage":0,"counters":{},"summoning_sick":False}
