    state,player,bot=threshold_state();own=permanent(3780,"Own Enchantment","Enchantment","player");enemy=permanent(3781,"Enemy Enchantment","Enchantment","bot");player["battlefield"]=[own];bot["battlefield"]=[enemy];spell={**card(3782,"Cleansing Meditation","Sorcery"),"oracle_text":"Destroy all enchantments.\nThreshold — If there are seven or more cards in your graveyard, instead destroy all enchantments, then return all cards in your graveyard destroyed this way to the battlefield.","instance_id":"cleansing-meditation","owner_id":"player","controller_id":"player"};state["stack"]=[{"id":"cleansing-stack","kind":"spell","card":spell,"controller_id":"player","target_id":None,"cast_source_zone":"hand"}];state=perform_action(state,"player",{"type":"resolve"});player=next(p for p in state["players"] if p["id"]=="player");bot=next(p for p in state["players"] if p["id"]=="bot");assert any(entry["instance_id"]==own["instance_id"] for entry in player["battlefield"]) and any(entry["instance_id"]==enemy["instance_id"] for entry in bot["graveyard"]) and not any(entry["instance_id"]==enemy["instance_id"] for entry in bot["battlefield"])
    state,player,bot=threshold_state();victim=permanent(3790,"Rancid Target","Land","bot");ally=permanent(3791,"Rancid Ally","Creature — Bear","player","2","2");enemy=permanent(3792,"Rancid Enemy","Creature — Bear","bot","2","2");player["battlefield"]=[ally];bot["battlefield"]=[victim,enemy];spell={**card(3793,"Rancid Earth","Sorcery"),"oracle_text":"Destroy target land.\nThreshold — If there are seven or more cards in your graveyard, instead destroy that land and Rancid Earth deals 1 damage to each creature and each player.","instance_id":"rancid-earth","owner_id":"player","controller_id":"player"};state["stack"]=[{"id":"rancid-stack","kind":"spell","card":spell,"controller_id":"player","target_id":victim["instance_id"],"cast_source_zone":"hand"}];state=perform_action(state,"player",{"type":"resolve"});player=next(p for p in state["players"] if p["id"]=="player");bot=next(p for p in state["players"] if p["id"]=="bot");ally=next(entry for entry in player["battlefield"] if entry["instance_id"]==ally["instance_id"]);enemy=next(entry for entry in bot["battlefield"] if entry["instance_id"]==enemy["instance_id"]);assert any(entry["instance_id"]==victim["instance_id"] for entry in bot["graveyard"]) and ally["damage"]==enemy["damage"]==1 and player["life"]==bot["life"]==19
    state,player,bot=threshold_state();victim=permanent(3800,"Sledge Target","Creature — Bear","bot","2","5");bot["battlefield"]=[victim];spell={**card(3801,"Kamahl's Sledge","Sorcery"),"oracle_text":"Kamahl's Sledge deals 4 damage to target creature.\nThreshold — If there are seven or more cards in your graveyard, instead Kamahl's Sledge deals 4 damage to that creature and 4 damage to that creature's controller.","instance_id":"kamahls-sledge","owner_id":"player","controller_id":"player"};state["stack"]=[{"id":"sledge-stack","kind":"spell","card":spell,"controller_id":"player","target_id":victim["instance_id"],"cast_source_zone":"hand"}];state=perform_action(state,"player",{"type":"resolve"});bot=next(p for p in state["players"] if p["id"]=="bot");victim=next(entry for entry in bot["battlefield"] if entry["instance_id"]==victim["instance_id"]);assert victim["damage"]==4 and bot["life"]==16


