def test_threshold_damage_prevention_and_global_menace_use_temporary_rules_state():
    state=kept_game();player=next(entry for entry in state["players"] if entry["id"]=="player");bot=next(entry for entry in state["players"] if entry["id"]=="bot");target={**card(4300,"Healed Target","Creature — Human","{1}{W}","2","6"),"instance_id":"healed-target","owner_id":"player","controller_id":"player","tapped":False,"damage":0,"counters":{},"summoning_sick":False};source={**card(4301,"Damage Source","Creature — Goblin","{R}","5","5"),"instance_id":"damage-source","owner_id":"bot","controller_id":"bot","tapped":False,"damage":0,"counters":{},"summoning_sick":False};player["battlefield"]=[target];bot["battlefield"]=[source]
    prevention={**card(4302,"Hallowed Healer ability","Ability"),"oracle_text":"Prevent the next 4 damage that would be dealt to any target this turn.","instance_id":"healer-ability","owner_id":"player","controller_id":"player"};state["stack"]=[{"id":"healer-stack","kind":"ability","card":prevention,"controller_id":"player","target_id":target["instance_id"]}];state=perform_action(state,"player",{"type":"resolve"});player=next(entry for entry in state["players"] if entry["id"]=="player");target=player["battlefield"][0];game_engine._damage_permanent(state,target,5,source);assert target["damage"]==1 and target["damage_prevention"]==0
    target["damage"]=0;target["damage_prevention"]=4;unpreventable={**source,"oracle_text":"Damage dealt by this creature can't be prevented."};game_engine._damage_permanent(state,target,5,unpreventable);assert target["damage"]==5 and target["damage_prevention"]==4;_begin_next_turn(state);player=next(entry for entry in state["players"] if entry["id"]=="player");assert "damage_prevention" not in player["battlefield"][0]

    state=kept_game();player=next(entry for entry in state["players"] if entry["id"]=="player");bot=next(entry for entry in state["players"] if entry["id"]=="bot");ally={**target,"instance_id":"menace-ally","damage":0};enemy={**source,"instance_id":"menace-enemy","damage":0};player["battlefield"]=[ally];bot["battlefield"]=[enemy];spell={**card(4303,"Demoralize","Instant","{2}{R}"),"oracle_text":"All creatures gain menace until end of turn.\nThreshold — If there are seven or more cards in your graveyard, creatures can't block this turn.","instance_id":"base-demoralize","owner_id":"player","controller_id":"player"};state["stack"]=[{"id":"base-demoralize-stack","kind":"spell","card":spell,"controller_id":"player","target_id":None,"cast_source_zone":"hand"}];state=perform_action(state,"player",{"type":"resolve"});assert all(_has_keyword(permanent,"Menace") for owner in state["players"] for permanent in owner["battlefield"] if "Creature" in permanent["type_line"]) and all(permanent.get("cant_block_until_turn") is None for owner in state["players"] for permanent in owner["battlefield"])


def test_repentant_vampire_visibly_triggers_only_for_creatures_it_damaged_this_turn():
    def setup(grave_count=7):
        state=kept_game();player=next(entry for entry in state["players"] if entry["id"]=="player");bot=next(entry for entry in state["players"] if entry["id"]=="bot")
        vampire={**card(4310,"Repentant Vampire","Creature — Vampire","{3}{B}{B}","3","3"),"oracle_text":"Flying\nWhenever a creature dealt damage by this creature this turn dies, put a +1/+1 counter on this creature.\nThreshold — As long as there are seven or more cards in your graveyard, this creature is white and has \"{T}: Destroy target black creature.\"","instance_id":"repentant-vampire","owner_id":"player","controller_id":"player","tapped":False,"damage":0,"counters":{},"summoning_sick":False}
        victim={**card(4311,"Repentant Victim","Creature — Bear","{1}{G}","2","2"),"instance_id":"repentant-victim","owner_id":"bot","controller_id":"bot","tapped":False,"damage":0,"counters":{},"summoning_sick":False}
        player["graveyard"]=[{**card(4320+index,f"Repentant Grave {index}","Sorcery"),"instance_id":f"repentant-grave-{index}","owner_id":"player","controller_id":"player"} for index in range(grave_count)];player["battlefield"]=[vampire];bot["battlefield"]=[victim];_sync_city_blessing(state);return state,player,bot,vampire,victim

    state,player,bot,vampire,victim=setup();game_engine._damage_permanent(state,victim,1,vampire);game_engine._destroy_permanent(state,bot,victim);assert len(state["stack"])==1 and state["stack"][-1]["kind"]=="trigger" and vampire.get("counters",{}).get("+1/+1",0)==0
    state=perform_action(state,"player",{"type":"resolve"});vampire=next(entry for entry in next(owner for owner in state["players"] if owner["id"]=="player")["battlefield"] if entry["instance_id"]=="repentant-vampire");assert vampire["counters"]["+1/+1"]==1

    state,player,bot,vampire,victim=setup();game_engine._damage_permanent(state,victim,1,vampire);_begin_next_turn(state);game_engine._destroy_permanent(state,bot,victim);assert not state["stack"]


def test_hallowed_healer_exact_card_switches_from_two_to_four_damage_prevention():
    def setup(grave_count):
        state=kept_game();player=next(entry for entry in state["players"] if entry["id"]=="player");bot=next(entry for entry in state["players"] if entry["id"]=="bot")
        healer={**card(4340,"Hallowed Healer","Creature — Human Cleric","{2}{W}","1","1"),"oracle_text":"{T}: Prevent the next 2 damage that would be dealt to any target this turn.\nThreshold — {T}: Prevent the next 4 damage that would be dealt to any target this turn. Activate only if there are seven or more cards in your graveyard.","instance_id":"hallowed-healer","owner_id":"player","controller_id":"player","tapped":False,"damage":0,"counters":{},"summoning_sick":False}
        target={**card(4341,"Healer Target","Creature — Soldier","{1}{W}","2","6"),"instance_id":"healer-target-exact","owner_id":"player","controller_id":"player","tapped":False,"damage":0,"counters":{},"summoning_sick":False};source={**card(4342,"Healer Damage","Creature — Goblin","{R}","5","5"),"instance_id":"healer-damage","owner_id":"bot","controller_id":"bot","tapped":False,"damage":0,"counters":{},"summoning_sick":False}
        player["graveyard"]=[{**card(4350+index,f"Healer Grave {index}","Sorcery"),"instance_id":f"healer-grave-{index}","owner_id":"player","controller_id":"player"} for index in range(grave_count)];player["battlefield"]=[healer,target];bot["battlefield"]=[source];_sync_city_blessing(state);return state,target,source
    for grave_count,prevented in ((6,2),(7,4)):
        state,target,source=setup(grave_count);actions=[action for action in legal_actions(state,"player") if action.get("card_id")=="hallowed-healer"];amounts={2 if "next 2 damage" in action["label"] else 4 for action in actions};assert amounts==({2} if grave_count==6 else {2,4})
        action=next(action for action in actions if f"next {prevented} damage" in action["label"]);state=perform_action(state,"player",{"type":"activate","card_id":"hallowed-healer","ability_index":action["ability_index"],"target_id":target["instance_id"]});state=perform_action(state,"player",{"type":"resolve"});player=next(entry for entry in state["players"] if entry["id"]=="player");target=next(entry for entry in player["battlefield"] if entry["instance_id"]=="healer-target-exact");game_engine._damage_permanent(state,target,5,source);assert target["damage"]==5-prevented


