def test_chlorophant_exact_threshold_upkeep_presents_each_optional_counter_separately():
    def trigger_count(grave_count):
        state=kept_game();player=next(entry for entry in state["players"] if entry["id"]=="player");chlorophant={**card(4430,"Chlorophant","Creature — Elemental","{G}{G}{G}","1","1"),"oracle_text":"At the beginning of your upkeep, you may put a +1/+1 counter on this creature.\nThreshold — As long as there are seven or more cards in your graveyard, this creature has \"At the beginning of your upkeep, you may put another +1/+1 counter on this creature.\"","instance_id":"chlorophant","owner_id":"player","controller_id":"player","tapped":False,"damage":0,"counters":{},"summoning_sick":False};player["graveyard"]=[{**card(4440+index,f"Chlorophant Grave {index}","Sorcery"),"instance_id":f"chlorophant-grave-{index}","owner_id":"player","controller_id":"player"} for index in range(grave_count)];player["battlefield"]=[chlorophant];_sync_city_blessing(state);_queue_triggers(state,"upkeep",None,player);accepted=0
        while any(action["type"]=="accept_trigger" for action in legal_actions(state,"player")):
            state=perform_action(state,"player",{"type":"accept_trigger"});accepted+=1
        assert len(state["stack"])==accepted
        while state["stack"]:state=perform_action(state,"player",{"type":"resolve"})
        player=next(entry for entry in state["players"] if entry["id"]=="player");return accepted,player["battlefield"][0].get("counters",{}).get("+1/+1",0)
    assert trigger_count(6)==(1,1);assert trigger_count(7)==(2,2)


