def test_delirium_spell_replacements_resolve_the_stronger_exact_card_effects():
    state=kept_game();player=next(entry for entry in state["players"] if entry["id"]=="player");bot=next(entry for entry in state["players"] if entry["id"]=="bot");player["graveyard"]=[{**card(4490,"Delirium Artifact","Artifact"),"instance_id":"spell-delirium-artifact","owner_id":"player","controller_id":"player"},{**card(4491,"Delirium Creature","Creature — Spirit"),"instance_id":"spell-delirium-creature","owner_id":"player","controller_id":"player"},{**card(4492,"Delirium Instant","Instant"),"instance_id":"spell-delirium-instant","owner_id":"player","controller_id":"player"},{**card(4493,"Delirium Land","Land"),"instance_id":"spell-delirium-land","owner_id":"player","controller_id":"player"}]
    target={**card(4494,"Delirium Target","Creature — Beast","{4}{G}","4","8"),"instance_id":"delirium-target","owner_id":"bot","controller_id":"bot","tapped":False,"damage":0,"counters":{},"summoning_sick":False};bot["battlefield"]=[target]
    spells=[
        ({**card(4495,"Might Beyond Reason","Instant","{3}{G}"),"oracle_text":"Put two +1/+1 counters on target creature.\nDelirium — Put three +1/+1 counters on that creature instead if there are four or more card types among cards in your graveyard."},"+1/+1"),
        ({**card(4496,"Unholy Heat","Instant","{R}"),"oracle_text":"Unholy Heat deals 2 damage to target creature or planeswalker.\nDelirium — Unholy Heat deals 6 damage instead if there are four or more card types among cards in your graveyard."},"damage"),
        ({**card(4497,"Violent Urge","Instant","{R}"),"oracle_text":"Target creature gets +1/+0 and gains first strike until end of turn.\nDelirium — If there are four or more card types among cards in your graveyard, that creature gains double strike until end of turn."},"combat"),
    ]
    for index,(spell,kind) in enumerate(spells):
        spell.update({"instance_id":f"delirium-spell-{index}","owner_id":"player","controller_id":"player"});state["stack"]=[{"id":f"delirium-stack-{index}","kind":"spell","card":spell,"controller_id":"player","target_id":"delirium-target","cast_source_zone":"hand"}];state=perform_action(state,"player",{"type":"resolve"});bot=next(entry for entry in state["players"] if entry["id"]=="bot");target=next(entry for entry in bot["battlefield"] if entry["instance_id"]=="delirium-target")
        if kind=="+1/+1":assert target["counters"]["+1/+1"]==3
        elif kind=="damage":assert target["damage"]==6
        else:assert target.get("temporary_power")==1 and _has_keyword(target,"First strike") and _has_keyword(target,"Double strike"),(target,state["log"][-5:])


