def test_demolisher_spawn_delirium_attack_bonus_waits_on_the_visible_stack():
    def setup(active):
        state=kept_game();state["phase"]="combat";player=next(entry for entry in state["players"] if entry["id"]=="player");spawn={**card(4580,"Demolisher Spawn","Creature — Horror","{5}{G}{G}","7","7"),"oracle_text":"Trample, haste\nDelirium — Whenever this creature attacks, if there are four or more card types among cards in your graveyard, other attacking creatures get +4/+4 until end of turn.","instance_id":"demolisher-spawn","owner_id":"player","controller_id":"player","tapped":True,"damage":0,"counters":{},"summoning_sick":False};ally={**card(4581,"Spawn Ally","Creature — Beast","{2}{G}","3","3"),"instance_id":"spawn-ally","owner_id":"player","controller_id":"player","tapped":True,"damage":0,"counters":{},"summoning_sick":False};player["battlefield"]=[spawn,ally];types=["Artifact Creature — Golem","Instant"]+(["Land"] if active else []);player["graveyard"]=[{**card(4582+index,f"Spawn Grave {index}",type_line),"instance_id":f"spawn-grave-{index}","owner_id":"player","controller_id":"player"} for index,type_line in enumerate(types)];state["combat"]["attackers"]=[spawn["instance_id"],ally["instance_id"]];_sync_city_blessing(state);_queue_triggers(state,"attackers_declared",None,player,sources_override=[(player,spawn)]);return state,spawn,ally
    state,spawn,ally=setup(False);assert not state["stack"] and _parse_stats(ally,state)==(3,3)
    state,spawn,ally=setup(True);assert len(state["stack"])==1 and _parse_stats(ally,state)==(3,3);state=perform_action(state,"player",{"type":"resolve"});player=next(entry for entry in state["players"] if entry["id"]=="player");spawn=next(entry for entry in player["battlefield"] if entry["instance_id"]=="demolisher-spawn");ally=next(entry for entry in player["battlefield"] if entry["instance_id"]=="spawn-ally");assert _parse_stats(spawn,state)==(7,7) and _parse_stats(ally,state)==(7,7)


def test_delirium_automatic_transforms_resolve_from_the_stack_before_changing_faces():
    def setup(name,event):
        state=kept_game();player=next(entry for entry in state["players"] if entry["id"]=="player");front_text="Delirium — At the beginning of your upkeep, if there are four or more card types among cards in your graveyard, transform this creature." if event=="upkeep" else "{B}: Mill a card.\nDelirium — At the beginning of your end step, if there are four or more card types among cards in your graveyard, transform this enchantment.";back_name="Extricator of Flesh" if event=="upkeep" else "Ancient of the Equinox";front_type="Creature — Human Cleric" if event=="upkeep" else "Enchantment";back_type="Creature — Eldrazi Horror";permanent={**card(4600,name,front_type,"{2}{W}","0","3"),"oracle_text":front_text,"card_faces":[{"name":name,"oracle_text":front_text,"type_line":front_type,"power":"0","toughness":"3"},{"name":back_name,"oracle_text":"Trample, hexproof" if event=="end_step" else "Eldrazi you control have vigilance.","type_line":back_type,"power":"4" if event=="end_step" else "3","toughness":"4" if event=="end_step" else "5"}],"current_face":0,"instance_id":f"delirium-transform-{event}","owner_id":"player","controller_id":"player","tapped":False,"damage":0,"counters":{},"summoning_sick":False};player["graveyard"]=[{**card(4601,"Transform Relic","Artifact Creature — Golem"),"instance_id":f"transform-relic-{event}","owner_id":"player","controller_id":"player"},{**card(4602,"Transform Memory","Instant"),"instance_id":f"transform-memory-{event}","owner_id":"player","controller_id":"player"},{**card(4603,"Transform Ruin","Land"),"instance_id":f"transform-ruin-{event}","owner_id":"player","controller_id":"player"}];player["battlefield"]=[permanent];_sync_city_blessing(state);_queue_triggers(state,event,None,player);return state,permanent,back_name
    for name,event in (("Extricator of Sin","upkeep"),("Autumnal Gloom","end_step")):
        state,permanent,back_name=setup(name,event);assert len(state["stack"])==1 and permanent["current_face"]==0;state=perform_action(state,"player",{"type":"resolve"});player=next(entry for entry in state["players"] if entry["id"]=="player");transformed=player["battlefield"][0];assert transformed["current_face"]==1 and transformed["name"]==back_name


def test_kindly_stranger_transform_creates_a_separate_optional_destroy_choice():
    state=kept_game();state["phase"]="precombat_main";player=next(entry for entry in state["players"] if entry["id"]=="player");bot=next(entry for entry in state["players"] if entry["id"]=="bot");front_text="Delirium — {2}{B}: Transform this creature. Activate only if there are four or more card types among cards in your graveyard.";back_text="When this creature transforms into Demon-Possessed Witch, you may destroy target creature.";stranger={**card(4620,"Kindly Stranger","Creature — Human","{2}{B}","2","3"),"oracle_text":front_text,"card_faces":[{"name":"Kindly Stranger","oracle_text":front_text,"type_line":"Creature — Human","power":"2","toughness":"3"},{"name":"Demon-Possessed Witch","oracle_text":back_text,"type_line":"Creature — Human Shaman","power":"4","toughness":"3"}],"current_face":0,"instance_id":"kindly-stranger","owner_id":"player","controller_id":"player","tapped":False,"damage":0,"counters":{},"summoning_sick":False};victim={**card(4621,"Witch Victim","Creature — Bear","{2}","2","2"),"instance_id":"witch-victim","owner_id":"bot","controller_id":"bot","tapped":False,"damage":0,"counters":{},"summoning_sick":False};lands=[{**card(4622+index,f"Stranger Swamp {index}","Basic Land — Swamp"),"instance_id":f"stranger-swamp-{index}","owner_id":"player","controller_id":"player","tapped":False,"damage":0,"counters":{},"summoning_sick":False} for index in range(3)];player["graveyard"]=[{**card(4630,"Stranger Relic","Artifact Creature — Golem"),"instance_id":"stranger-relic","owner_id":"player","controller_id":"player"},{**card(4631,"Stranger Memory","Instant"),"instance_id":"stranger-memory","owner_id":"player","controller_id":"player"},{**card(4632,"Stranger Ruin","Land"),"instance_id":"stranger-ruin","owner_id":"player","controller_id":"player"}];player["battlefield"]=[stranger,*lands];bot["battlefield"]=[victim];_sync_city_blessing(state);action=next(action for action in legal_actions(state,"player") if action.get("card_id")=="kindly-stranger");state=perform_action(state,"player",{"type":"activate","card_id":"kindly-stranger","ability_index":action["ability_index"]});state=perform_action(state,"player",{"type":"resolve"});player=next(entry for entry in state["players"] if entry["id"]=="player");assert next(entry for entry in player["battlefield"] if entry["instance_id"]=="kindly-stranger")["name"]=="Demon-Possessed Witch";actions=legal_actions(state,"player");assert {action["type"] for action in actions}>={"choose_trigger_target","skip_trigger"}
    state=perform_action(state,"player",{"type":"choose_trigger_target","target_id":"witch-victim"});assert state["stack"][-1]["kind"]=="trigger";state=perform_action(state,"player",{"type":"resolve"});bot=next(entry for entry in state["players"] if entry["id"]=="bot");assert not bot["battlefield"]


def test_delirium_graveyard_return_uses_the_stack_and_applies_finality_replacement():
    for index,name,colors in ((4640,"Balustrade Wurm",("G","G")),(4650,"Resurrected Cultist",("B","B"))):
        state=kept_game();state["phase"]="precombat_main";player=next(entry for entry in state["players"] if entry["id"]=="player");type_line="Creature — Wurm" if "Wurm" in name else "Creature — Human Cleric";creature={**card(index,name,type_line,"{4}","5","5"),"oracle_text":f"Delirium — {{2}}{{{colors[0]}}}{{{colors[1]}}}: Return this card from your graveyard to the battlefield with a finality counter on it. Activate only if there are four or more card types among cards in your graveyard and only as a sorcery.","instance_id":name.casefold().replace(" ","-"),"owner_id":"player","controller_id":"player"};player["graveyard"]=[creature,{**card(index+1,"Return Relic","Artifact"),"instance_id":f"return-relic-{index}","owner_id":"player","controller_id":"player"},{**card(index+2,"Return Memory","Instant"),"instance_id":f"return-memory-{index}","owner_id":"player","controller_id":"player"},{**card(index+3,"Return Ruin","Land"),"instance_id":f"return-ruin-{index}","owner_id":"player","controller_id":"player"}];land_type="Basic Land — Forest" if colors[0]=="G" else "Basic Land — Swamp";player["battlefield"]=[{**card(index+4+land_index,f"Return Land {index} {land_index}",land_type),"instance_id":f"return-land-{index}-{land_index}","owner_id":"player","controller_id":"player","tapped":False,"damage":0,"counters":{},"summoning_sick":False} for land_index in range(4)];action=next(action for action in legal_actions(state,"player") if action.get("card_id")==creature["instance_id"] and action["type"]=="activate_graveyard");state=perform_action(state,"player",{"type":"activate_graveyard","card_id":creature["instance_id"]});player=next(entry for entry in state["players"] if entry["id"]=="player");assert creature["instance_id"] in {entry["instance_id"] for entry in player["graveyard"]} and state["stack"][-1]["kind"]=="ability"
        state=perform_action(state,"player",{"type":"resolve"});player=next(entry for entry in state["players"] if entry["id"]=="player");returned=next(entry for entry in player["battlefield"] if entry["instance_id"]==creature["instance_id"]);assert returned["counters"]["finality"]==1;game_engine._destroy_permanent(state,player,returned);player=next(entry for entry in state["players"] if entry["id"]=="player");assert returned["instance_id"] in {entry["instance_id"] for entry in player["exile"]} and returned["instance_id"] not in {entry["instance_id"] for entry in player["graveyard"]}


def test_prophetic_titan_delirium_modal_trigger_forces_both_then_pauses_for_each_choice():
    state=kept_game();player=next(entry for entry in state["players"] if entry["id"]=="player");bot=next(entry for entry in state["players"] if entry["id"]=="bot");text="Delirium — When this creature enters, choose one. If there are four or more card types among cards in your graveyard, choose both instead.\n• This creature deals 4 damage to any target.\n• Look at the top four cards of your library. Put one of them into your hand and the rest on the bottom of your library in a random order.";titan={**card(4670,"Prophetic Titan","Creature — Giant Wizard","{4}{U}{R}","4","4"),"oracle_text":text,"instance_id":"prophetic-titan","owner_id":"player","controller_id":"player","tapped":False,"damage":0,"counters":{},"summoning_sick":False};victim={**card(4671,"Titan Target","Creature — Beast","{5}","5","8"),"instance_id":"titan-target","owner_id":"bot","controller_id":"bot","tapped":False,"damage":0,"counters":{},"summoning_sick":False};top=[{**card(4672+index,f"Titan Top {index}","Sorcery"),"instance_id":f"titan-top-{index}","owner_id":"player","controller_id":"player"} for index in range(4)];player["library"].extend(top);player["graveyard"]=[{**card(4680,"Titan Relic","Artifact Creature — Golem"),"instance_id":"titan-relic","owner_id":"player","controller_id":"player"},{**card(4681,"Titan Memory","Instant"),"instance_id":"titan-memory","owner_id":"player","controller_id":"player"},{**card(4682,"Titan Ruin","Land"),"instance_id":"titan-ruin","owner_id":"player","controller_id":"player"}];player["battlefield"]=[titan];bot["battlefield"]=[victim];_sync_city_blessing(state);_queue_triggers(state,"enters",titan,player,sources_override=[(player,titan)]);actions=legal_actions(state,"player");assert {action["type"] for action in actions}>={"choose_trigger_target"} and not any(action["type"]=="choose_trigger_mode" for action in actions)
    state=perform_action(state,"player",{"type":"choose_trigger_target","target_id":"titan-target"});state=perform_action(state,"player",{"type":"resolve"});bot=next(entry for entry in state["players"] if entry["id"]=="bot");assert bot["battlefield"][0]["damage"]==4 and state["pending_library_search"]["look_bottom_unchosen"]
    state=perform_action(state,"player",{"type":"search_library","card_ids":["titan-top-2"]});player=next(entry for entry in state["players"] if entry["id"]=="player");assert "titan-top-2" in {entry["instance_id"] for entry in player["hand"]} and {entry["instance_id"] for entry in player["library"][:3]}=={"titan-top-0","titan-top-1","titan-top-3"}


def test_lets_play_a_game_delirium_exposes_one_or_more_modes_on_the_cast_action():
    state=kept_game();state["phase"]="precombat_main";player=next(entry for entry in state["players"] if entry["id"]=="player");spell={**card(4690,"Let's Play a Game","Sorcery","{3}{B}{B}"),"oracle_text":"Delirium — Choose one. If there are four or more card types among cards in your graveyard, choose one or more instead.\n• Creatures your opponents control get -1/-1 until end of turn.\n• Each opponent discards two cards.\n• Each opponent loses 3 life and you gain 3 life.","instance_id":"lets-play-a-game","owner_id":"player","controller_id":"player"};player["hand"]=[spell];player["graveyard"]=[{**card(4691,"Game Relic","Artifact Creature — Golem"),"instance_id":"game-relic","owner_id":"player","controller_id":"player"},{**card(4692,"Game Memory","Instant"),"instance_id":"game-memory","owner_id":"player","controller_id":"player"},{**card(4693,"Game Ruin","Land"),"instance_id":"game-ruin","owner_id":"player","controller_id":"player"}];player["battlefield"]=[{**card(4694+index,f"Game Swamp {index}","Basic Land — Swamp"),"instance_id":f"game-swamp-{index}","owner_id":"player","controller_id":"player","tapped":False,"damage":0,"counters":{},"summoning_sick":False} for index in range(5)];action=next(action for action in legal_actions(state,"player") if action.get("card_id")=="lets-play-a-game");assert action["mode_min"]==1 and action["mode_max"]==3 and len(action["modes"])==3


def test_rollercrusher_ride_doubles_only_controlled_noncombat_damage_at_delirium():
    state=kept_game();player=next(entry for entry in state["players"] if entry["id"]=="player");bot=next(entry for entry in state["players"] if entry["id"]=="bot");ride={**card(4710,"The Rollercrusher Ride","Enchantment","{X}{2}{R}"),"oracle_text":"Delirium — If a source you control would deal noncombat damage to a permanent or player while there are four or more card types among cards in your graveyard, it deals double that damage instead.","instance_id":"rollercrusher-ride","owner_id":"player","controller_id":"player","tapped":False,"damage":0,"counters":{},"summoning_sick":False};source={**card(4711,"Ride Source","Creature — Goblin","{R}","2","2"),"instance_id":"ride-source","owner_id":"player","controller_id":"player","tapped":False,"damage":0,"counters":{},"summoning_sick":False};victim={**card(4712,"Ride Victim","Creature — Giant","{5}","5","8"),"instance_id":"ride-victim","owner_id":"bot","controller_id":"bot","tapped":False,"damage":0,"counters":{},"summoning_sick":False};player["battlefield"]=[ride,source];bot["battlefield"]=[victim];player["graveyard"]=[{**card(4713,"Ride Relic","Artifact Creature — Golem"),"instance_id":"ride-relic","owner_id":"player","controller_id":"player"},{**card(4714,"Ride Memory","Instant"),"instance_id":"ride-memory","owner_id":"player","controller_id":"player"},{**card(4715,"Ride Ruin","Land"),"instance_id":"ride-ruin","owner_id":"player","controller_id":"player"}];_sync_city_blessing(state);game_engine._damage_permanent(state,victim,2,source);game_engine._damage_player(state,bot,2,source);assert victim["damage"]==4 and bot["life"]==16
    victim["damage"]=0;game_engine._damage_permanent(state,victim,2,source,True);game_engine._damage_player(state,bot,2,source,True);assert victim["damage"]==2 and bot["life"]==14


