            state=kept_game();player=next(entry for entry in state["players"] if entry["id"]=="player");spell={**card(4990+case_index,name,"Sorcery","{2}"),"oracle_text":text,"instance_id":f"search-spell-{case_index}-{active}","owner_id":"player","controller_id":"player"};player["library"]=[{**card(5000+case_index*10+i,card_name,type_line),"instance_id":f"search-candidate-{case_index}-{i}","owner_id":"player","controller_id":"player"} for i,(card_name,type_line) in enumerate(candidates)];types=["Artifact Creature — Golem","Instant"]+(["Land"] if active else []);player["graveyard"]=[{**card(5030+i,f"Search Grave {i}",type_line),"instance_id":f"search-grave-{case_index}-{active}-{i}","owner_id":"player","controller_id":"player"} for i,type_line in enumerate(types)];state["stack"]=[{"id":f"search-stack-{case_index}-{active}","kind":"spell","card":spell,"controller_id":"player","target_id":None,"cast_source_zone":"hand"}];state=perform_action(state,"player",{"type":"resolve"});action=next(action for action in legal_actions(state,"player") if action["type"]=="search_library");assert {candidate["name"] for candidate in action["cards"]}==(active_names if active else inactive_names)


