        state=kept_game();player=next(entry for entry in state["players"] if entry["id"]=="player");bot=next(entry for entry in state["players"] if entry["id"]=="bot");spell={**card(5140,"To the Slaughter","Instant","{2}{B}"),"oracle_text":"Target player sacrifices a creature or planeswalker of their choice.\nDelirium — If there are four or more card types among cards in your graveyard, instead that player sacrifices a creature and a planeswalker of their choice.","instance_id":f"to-slaughter-{active}","owner_id":"player","controller_id":"player"};creature={**card(5141,"Slaughter Creature","Creature — Beast","{3}","3","3"),"instance_id":"slaughter-creature","owner_id":"bot","controller_id":"bot","tapped":False,"damage":0,"counters":{},"summoning_sick":False};walker={**card(5142,"Slaughter Walker","Legendary Planeswalker — Test","{3}"),"loyalty":"4","instance_id":"slaughter-walker","owner_id":"bot","controller_id":"bot","tapped":False,"damage":0,"counters":{"loyalty":4},"summoning_sick":False};bot["battlefield"]=[creature,walker];types=["Artifact Creature — Golem","Instant"]+(["Land"] if active else []);player["graveyard"]=[{**card(5150+i,f"Slaughter Grave {i}",type_line),"instance_id":f"slaughter-grave-{active}-{i}","owner_id":"player","controller_id":"player"} for i,type_line in enumerate(types)];state["stack"]=[{"id":f"slaughter-stack-{active}","kind":"spell","card":spell,"controller_id":"player","target_id":"bot","cast_source_zone":"hand"}];state=perform_action(state,"player",{"type":"resolve"});action=next(action for action in legal_actions(state,"bot") if action["type"]=="sacrifice_permanents");assert set(action["card_ids"])==({"slaughter-creature"} if active else {"slaughter-creature","slaughter-walker"});state=perform_action(state,"bot",{"type":"sacrifice_permanents","card_ids":["slaughter-creature"]});bot=next(entry for entry in state["players"] if entry["id"]=="bot")
        if active:action=next(action for action in legal_actions(state,"bot") if action["type"]=="sacrifice_permanents");assert action["card_ids"]==["slaughter-walker"];state=perform_action(state,"bot",{"type":"sacrifice_permanents","card_ids":["slaughter-walker"]});bot=next(entry for entry in state["players"] if entry["id"]=="bot");assert not bot["battlefield"]
        else:assert {card["instance_id"] for card in bot["battlefield"]}=={"slaughter-walker"} and not state.get("pending_sacrifice")


