    for active in (False,True):
        state=kept_game();player=next(entry for entry in state["players"] if entry["id"]=="player");bot=next(entry for entry in state["players"] if entry["id"]=="bot");spell={**card(5170,"Beastie Beatdown","Sorcery","{3}{G}"),"oracle_text":"Choose target creature you control and target creature an opponent controls.\nDelirium — If there are four or more card types among cards in your graveyard, put two +1/+1 counters on the creature you control.\nThe creature you control deals damage equal to its power to the creature an opponent controls.","instance_id":f"beastie-beatdown-{active}","owner_id":"player","controller_id":"player"};attacker={**card(5171,"Beatdown Beastie","Creature — Beast","{2}","2","3"),"instance_id":"beatdown-beastie","owner_id":"player","controller_id":"player","tapped":False,"damage":0,"counters":{},"summoning_sick":False};victim={**card(5172,"Beatdown Target","Creature — Giant","{5}","5","7"),"instance_id":"beatdown-target","owner_id":"bot","controller_id":"bot","tapped":False,"damage":0,"counters":{},"summoning_sick":False};player["battlefield"]=[attacker];bot["battlefield"]=[victim];types=["Artifact Creature — Golem","Instant"]+(["Land"] if active else []);player["graveyard"]=[{**card(5180+i,f"Beatdown Grave {i}",type_line),"instance_id":f"beatdown-grave-{active}-{i}","owner_id":"player","controller_id":"player"} for i,type_line in enumerate(types)];rules=game_engine._delirium_rules_card(spell,player);steps=game_engine._fight_target_steps(state,"player",rules);assert [{target["id"] for target in step["targets"]} for step in steps]==[{"beatdown-beastie"},{"beatdown-target"}];state["stack"]=[{"id":f"beatdown-stack-{active}","kind":"spell","card":spell,"controller_id":"player","target_id":None,"target_ids":["beatdown-beastie","beatdown-target"],"cast_source_zone":"hand"}];state=perform_action(state,"player",{"type":"resolve"});player=next(entry for entry in state["players"] if entry["id"]=="player");bot=next(entry for entry in state["players"] if entry["id"]=="bot");attacker=player["battlefield"][0];victim=bot["battlefield"][0];assert attacker["damage"]==0 and attacker.get("counters",{}).get("+1/+1",0)==(2 if active else 0) and victim["damage"]==(4 if active else 2)


