    island={**card(5281,"Scuttletide Island","Basic Land — Island"),"instance_id":"scuttletide-island","owner_id":"player","controller_id":"player","tapped":False,"damage":0,"counters":{},"summoning_sick":False};discard={**card(5282,"Scuttletide Discard","Sorcery"),"instance_id":"scuttletide-discard","owner_id":"player","controller_id":"player"};player["battlefield"]=[scuttletide,island];player["hand"]=[discard];_sync_city_blessing(state)
