    state=perform_action(state,"player",{"type":"activate","card_id":"scuttletide","ability_index":action["ability_index"],"cost_card_ids":["scuttletide-discard"]});player=next(entry for entry in state["players"] if entry["id"]=="player");assert "scuttletide-discard" in {card["instance_id"] for card in player["graveyard"]} and not any(card.get("token") for card in player["battlefield"]) and state["stack"]
