    pick={**card(5560,"Pick the Brain","Sorcery","{2}{B}"),"oracle_text":"Target opponent reveals their hand. You choose a nonland card from it and exile that card.\nDelirium — If there are four or more card types among cards in your graveyard, search that player's graveyard, hand, and library for any number of cards with the same name as that card, exile those cards, then that player shuffles.","instance_id":"pick-brain","owner_id":"player","controller_id":"player"}
    copies=[{**card(5561+i,"Hidden Scheme","Sorcery","{3}{B}"),"instance_id":f"hidden-scheme-{i}","owner_id":"bot","controller_id":"bot"} for i in range(4)];land={**card(5565,"Hidden Swamp","Basic Land — Swamp"),"instance_id":"hidden-land","owner_id":"bot","controller_id":"bot"};bot["hand"]=[copies[0],land];bot["graveyard"]=[copies[1]];bot["library"].extend([copies[2],copies[3]])
    player["graveyard"]=[{**card(5570,"Pick Relic","Artifact Creature — Golem"),"instance_id":"pick-relic","owner_id":"player","controller_id":"player"},{**card(5571,"Pick Memory","Instant"),"instance_id":"pick-memory","owner_id":"player","controller_id":"player"},{**card(5572,"Pick Ruin","Land"),"instance_id":"pick-ruin","owner_id":"player","controller_id":"player"}];state["stack"]=[{"id":"pick-stack","kind":"spell","card":pick,"controller_id":"player","target_id":"bot","cast_source_zone":"hand"}];_sync_city_blessing(state)
    state=perform_action(state,"player",{"type":"resolve"});actions=legal_actions(state,"player");assert [action["card_id"] for action in actions if action["type"]=="choose_same_name_cards"]==["hidden-scheme-0"] and not public_state(state,"bot")["pending_same_name_search"]["cards"]
    state=perform_action(state,"player",{"type":"choose_same_name_cards","card_id":"hidden-scheme-0"});action=next(action for action in legal_actions(state,"player") if action["type"]=="choose_same_name_cards");assert set(action["card_ids"])=={"hidden-scheme-1","hidden-scheme-2","hidden-scheme-3"} and not public_state(state,"bot")["pending_same_name_search"]["cards"]
    state=perform_action(state,"player",{"type":"choose_same_name_cards","card_ids":["hidden-scheme-1","hidden-scheme-3"]});bot=next(entry for entry in state["players"] if entry["id"]=="bot");assert {card["instance_id"] for card in bot["exile"]}>={"hidden-scheme-0","hidden-scheme-1","hidden-scheme-3"} and "hidden-scheme-2" in {card["instance_id"] for card in bot["library"]} and not state.get("pending_same_name_search")


