    state=perform_action(state,"player",{"type":"resolve"});bot=next(entry for entry in state["players"] if entry["id"]=="bot");assert "repeated-doom-stack" in {card["instance_id"] for card in bot["graveyard"]};action=next(action for action in legal_actions(state,"player") if action["type"]=="choose_same_name_cards");assert set(action["card_ids"])=={"repeated-doom-stack","repeated-doom-copy"}
