def test_winter_cynical_opportunist_pauses_for_four_types_then_a_finality_permanent():
    state=kept_game();player=next(entry for entry in state["players"] if entry["id"]=="player")
    winter={**card(5600,"Winter, Cynical Opportunist","Legendary Creature — Human Warlock","{2}{B}{G}","2","5"),"oracle_text":"Deathtouch\nWhenever Winter attacks, mill three cards.\nDelirium — At the beginning of your end step, you may exile any number of cards from your graveyard with four or more card types among them. If you do, put a permanent card from among them onto the battlefield with a finality counter on it.","instance_id":"winter-cynical","owner_id":"player","controller_id":"player","tapped":False,"damage":0,"counters":{},"summoning_sick":False}
    selected=[{**card(5601,"Winter Relic Beast","Artifact Creature — Beast","{3}","3","3"),"instance_id":"winter-relic-beast","owner_id":"player","controller_id":"player"},{**card(5602,"Winter Memory","Instant"),"instance_id":"winter-memory","owner_id":"player","controller_id":"player"},{**card(5603,"Winter Ruin","Land"),"instance_id":"winter-ruin","owner_id":"player","controller_id":"player"}];extra={**card(5604,"Winter Extra","Sorcery"),"instance_id":"winter-extra","owner_id":"player","controller_id":"player"};player["battlefield"]=[winter];player["graveyard"]=[*selected,extra];_sync_city_blessing(state);_queue_triggers(state,"end_step",None,player);assert {action["type"] for action in legal_actions(state,"player")}>={"accept_trigger","skip_trigger"}
    state=perform_action(state,"player",{"type":"accept_trigger"});state=perform_action(state,"player",{"type":"resolve"});action=next(action for action in legal_actions(state,"player") if action["type"]=="choose_winter_exile");assert set(action["card_ids"])=={card["instance_id"] for card in [*selected,extra]}
    with pytest.raises(RuleViolation,match="at least four card types"):perform_action(state,"player",{"type":"choose_winter_exile","card_ids":["winter-memory","winter-extra"]})
    state=perform_action(state,"player",{"type":"choose_winter_exile","card_ids":[card["instance_id"] for card in selected]});actions=[action for action in legal_actions(state,"player") if action["type"]=="choose_zone_card"];assert {action["card_id"] for action in actions}=={"winter-relic-beast","winter-ruin"}
    state=perform_action(state,"player",{"type":"choose_zone_card","card_id":"winter-relic-beast"});player=next(entry for entry in state["players"] if entry["id"]=="player");returned=next(card for card in player["battlefield"] if card["instance_id"]=="winter-relic-beast");assert returned["counters"]["finality"]==1 and {card["instance_id"] for card in player["exile"]}>={"winter-memory","winter-ruin"} and "winter-extra" in {card["instance_id"] for card in player["graveyard"]}


