    state=kept_game();player=next(entry for entry in state["players"] if entry["id"]=="player");courier={**card(5944,"Kinsbaile Courier","Creature — Kithkin Soldier","{2}{W}","2","1"),"oracle_text":"When this creature enters, put a +1/+1 counter on target creature.\nEncore {2}{W}","instance_id":"kinsbaile-courier","owner_id":"player","controller_id":"player","tapped":False,"damage":0,"counters":{},"summoning_sick":False};target={**card(5945,"Courier Ally","Creature — Kithkin","{2}","2","2"),"instance_id":"courier-ally","owner_id":"player","controller_id":"player","tapped":False,"damage":0,"counters":{},"summoning_sick":False};player["battlefield"]=[target];_enter_battlefield(state,player,[courier],"stack");state=perform_action(state,"player",{"type":"choose_trigger_target","target_id":"courier-ally"});state=perform_action(state,"player",{"type":"resolve"});assert next(entry for entry in next(owner for owner in state["players"] if owner["id"]=="player")["battlefield"] if entry["instance_id"]=="courier-ally")["counters"]["+1/+1"]==1
    for name,text,expected in (("Impulsive Pilferer","When this creature dies, create a Treasure token.",1),("Phyrexian Triniform","When this creature dies, create three 3/3 colorless Phyrexian Golem artifact creature tokens.",3),("Trove Tracker","When this creature dies, draw a card.",0)):
        state=kept_game();player=next(entry for entry in state["players"] if entry["id"]=="player");source={**card(5950,name,"Creature — Pirate","{2}","2","2"),"oracle_text":f"{text}\nEncore {{5}}","instance_id":f"shared-{name}","owner_id":"player","controller_id":"player","tapped":False,"damage":0,"counters":{},"summoning_sick":False};player["battlefield"]=[source];hand_before=len(player["hand"]);_leave_battlefield(state,player,source,"graveyard");state=perform_action(state,"player",{"type":"resolve"});player=next(entry for entry in state["players"] if entry["id"]=="player");tokens=[entry for entry in player["battlefield"] if entry.get("token")];assert len(tokens)==expected and (len(player["hand"])==hand_before+1 if name=="Trove Tracker" else len(player["hand"])==hand_before)


