def test_stomp_turns_off_all_damage_prevention_for_the_rest_of_the_turn_without_spending_shields():
    state=kept_game();player=next(entry for entry in state["players"] if entry["id"]=="player");bot=next(entry for entry in state["players"] if entry["id"]=="bot");source={**card(6350,"Later Damage","Creature — Archer","{1}","1","1"),"instance_id":"later-damage","owner_id":"player","controller_id":"player"};target={**card(6351,"Protected Target","Creature — Soldier","{3}","4","4"),"instance_id":"stomp-target","owner_id":"bot","controller_id":"bot","tapped":False,"damage":0,"counters":{"shield":1},"damage_prevention":5,"summoning_sick":False};player["battlefield"]=[source];bot["battlefield"]=[target];stomp={**card(6352,"Stomp","Instant — Adventure","{1}{R}"),"oracle_text":"Damage can't be prevented this turn. Stomp deals 2 damage to any target.","instance_id":"stomp","owner_id":"player","controller_id":"player"};state["stack"]=[{"id":"stomp-stack","kind":"spell","card":stomp,"controller_id":"player","target_id":"stomp-target","target_ids":[],"mode_indices":[],"mode_targets":[],"x_value":0}];state=perform_action(state,"player",{"type":"resolve"});bot=next(entry for entry in state["players"] if entry["id"]=="bot");target=bot["battlefield"][0];source=next(entry for entry in next(owner for owner in state["players"] if owner["id"]=="player")["battlefield"] if entry["instance_id"]=="later-damage");assert target["damage"]==2 and target["damage_prevention"]==5 and target["counters"]["shield"]==1
    game_engine._damage_permanent(state,target,1,source);assert target["damage"]==3 and target["damage_prevention"]==5 and target["counters"]["shield"]==1
    game_engine._begin_next_turn(state);target["damage_prevention"]=5;target["counters"]["shield"]=1;game_engine._damage_permanent(state,target,1,source);assert target["damage"]==0 and target["damage_prevention"]==4 and target["counters"]["shield"]==1


