def test_blitz_grants_haste_then_sacrifices_and_draws_at_the_end_step():
    state=kept_game();state["phase"]="precombat_main";player=next(entry for entry in state["players"] if entry["id"]=="player");lands=[{**card(6480+index,f"Blitz Forest {index}","Basic Land — Forest"),"instance_id":f"blitz-forest-{index}","owner_id":"player","controller_id":"player","tapped":False,"damage":0,"counters":{},"summoning_sick":False} for index in range(3)];creature={**card(6483,"Caldaia Guardian","Creature — Human Warrior","{3}{G}","4","3"),"oracle_text":"Blitz {2}{G} (If you cast this spell for its blitz cost, it gains haste and \"When this creature dies, draw a card.\" Sacrifice it at the beginning of the next end step.)","instance_id":"blitz-guardian","owner_id":"player","controller_id":"player"};player["battlefield"]=lands;player["hand"]=[creature];action=next(entry for entry in legal_actions(state,"player") if entry.get("source")=="blitz_hand");state=perform_action(state,"player",action);assert state["stack"][-1]["blitzed"] and all(land["tapped"] for land in next(entry for entry in state["players"] if entry["id"]=="player")["battlefield"])
    state=perform_action(state,"player",{"type":"resolve"});player=next(entry for entry in state["players"] if entry["id"]=="player");guardian=next(entry for entry in player["battlefield"] if entry["instance_id"]=="blitz-guardian");assert _has_keyword(guardian,"Haste") and guardian["blitz_sacrifice_turn"]==state["turn"];state["phase"]="postcombat_main";game_engine._advance_turn_phase(state);assert state["stack"][-1]["kind"]=="blitz_sacrifice_trigger";state=perform_action(state,"player",{"type":"resolve"});assert state["stack"][-1]["card"]["name"].endswith("Blitz draw");state=perform_action(state,"player",{"type":"resolve"});player=next(entry for entry in state["players"] if entry["id"]=="player");assert len(player["hand"])==1 and any(entry["instance_id"]=="blitz-guardian" for entry in player["graveyard"])


def test_blitz_supports_graveyard_life_and_hand_discard_cost_variants():
    state=kept_game();state["phase"]="precombat_main";player=next(entry for entry in state["players"] if entry["id"]=="player");lands=[{**card(6500+index,f"Blitz Mana {index}","Basic Land — Swamp"),"instance_id":f"blitz-mana-{index}","owner_id":"player","controller_id":"player","tapped":False,"damage":0,"counters":{},"summoning_sick":False} for index in range(4)];underdog={**card(6504,"Tenacious Underdog","Creature — Human Warrior","{1}{B}","3","2"),"oracle_text":"Blitz—{2}{B}{B}, Pay 2 life.\nYou may cast this card from your graveyard using its blitz ability.","instance_id":"tenacious-underdog","owner_id":"player","controller_id":"player"};player["battlefield"]=lands;player["graveyard"]=[underdog];action=next(entry for entry in legal_actions(state,"player") if entry.get("source")=="blitz_graveyard");state=perform_action(state,"player",action);player=next(entry for entry in state["players"] if entry["id"]=="player");assert player["life"]==18 and not player["graveyard"] and state["stack"][-1]["blitzed"]
    state=kept_game();state["phase"]="precombat_main";player=next(entry for entry in state["players"] if entry["id"]=="player");lands=[{**card(6510+index,f"Sabin Mountain {index}","Basic Land — Mountain"),"instance_id":f"sabin-mountain-{index}","owner_id":"player","controller_id":"player","tapped":False,"damage":0,"counters":{},"summoning_sick":False} for index in range(4)];fuel={**card(6514,"Sabin Fuel","Sorcery","{1}"),"instance_id":"sabin-fuel","owner_id":"player","controller_id":"player"};sabin={**card(6515,"Sabin, Master Monk","Legendary Creature — Human Monk","{4}{R}","4","4"),"oracle_text":"Double strike\nBlitz—{2}{R}{R}, Discard a card.\nYou may cast this card from your graveyard using its blitz ability.","instance_id":"sabin","owner_id":"player","controller_id":"player"};player["battlefield"]=lands;player["hand"]=[sabin,fuel];action=next(entry for entry in legal_actions(state,"player") if entry.get("source")=="blitz_hand");assert action["cost_options"]==["sabin-fuel"];state=perform_action(state,"player",{**action,"cost_card_ids":["sabin-fuel"]});player=next(entry for entry in state["players"] if entry["id"]=="player");assert any(entry["instance_id"]=="sabin-fuel" for entry in player["graveyard"]) and state["stack"][-1]["blitzed"]


def test_miracle_reveals_only_the_first_draw_and_pauses_until_cast_or_decline():
    state=kept_game();player=next(entry for entry in state["players"] if entry["id"]=="player");miracle={**card(6520,"Thunderous Wrath","Instant","{4}{R}{R}"),"oracle_text":"Thunderous Wrath deals 5 damage to any target.\nMiracle {R}","instance_id":"miracle-wrath","owner_id":"player","controller_id":"player"};later={**card(6521,"Later Miracle","Sorcery","{4}{U}"),"oracle_text":"Draw a card.\nMiracle {U}","instance_id":"later-miracle","owner_id":"player","controller_id":"player"};mountain={**card(6522,"Miracle Mountain","Basic Land — Mountain"),"instance_id":"miracle-mountain","owner_id":"player","controller_id":"player","tapped":False,"damage":0,"counters":{},"summoning_sick":False};player["battlefield"]=[mountain];player["library"].extend([later,miracle]);_draw(state,player,1);actions=legal_actions(state,"player");cast_action=next(entry for entry in actions if entry["type"]=="cast_miracle");hidden=public_state(state,"bot")["pending_miracle"];assert state["pending_miracle"]["card_id"]=="miracle-wrath" and cast_action["mana_cost"]=="{R}" and "bot" in {target["id"] for target in cast_action["targets"]} and any(entry["type"]=="decline_miracle" for entry in actions) and set(hidden)=={"player_id"}
    state=perform_action(state,"player",{**cast_action,"target_id":"bot"});assert state["pending_miracle"] is None and state["stack"][-1]["miracle_cast"];state=perform_action(state,"player",{"type":"resolve"});assert next(entry for entry in state["players"] if entry["id"]=="bot")["life"]==15;player=next(entry for entry in state["players"] if entry["id"]=="player");_draw(state,player,1);assert state.get("pending_miracle") is None
    state=kept_game();player=next(entry for entry in state["players"] if entry["id"]=="player");player["library"].append(miracle);_draw(state,player,1);state=perform_action(state,"player",{"type":"decline_miracle","card_id":"miracle-wrath"});assert state["pending_miracle"] is None and "Thunderous Wrath" not in state["log"][-1]["message"]


def test_miracle_x_costs_drive_token_counts_and_distinct_graveyard_targets():
    state=kept_game();player=next(entry for entry in state["players"] if entry["id"]=="player");lands=[{**card(6530+index,f"Miracle Plains {index}","Basic Land — Plains"),"instance_id":f"miracle-plains-{index}","owner_id":"player","controller_id":"player","tapped":False,"damage":0,"counters":{},"summoning_sick":False} for index in range(4)];angels={**card(6534,"Entreat the Angels","Sorcery","{X}{X}{W}{W}{W}"),"oracle_text":"Create X 4/4 white Angel creature tokens with flying.\nMiracle {X}{W}{W}","instance_id":"entreat-angels","owner_id":"player","controller_id":"player"};player["battlefield"]=lands;player["library"].append(angels);_draw(state,player,1);action=next(entry for entry in legal_actions(state,"player") if entry["type"]=="cast_miracle");assert action["x_max"]==2;state=perform_action(state,"player",{**action,"x_value":2});state=perform_action(state,"player",{"type":"resolve"});player=next(entry for entry in state["players"] if entry["id"]=="player");assert len([entry for entry in player["battlefield"] if "Angel" in entry.get("type_line","")])==2
    state=kept_game();player=next(entry for entry in state["players"] if entry["id"]=="player");lands=[{**card(6540+index,f"Dead Swamp {index}","Basic Land — Swamp"),"instance_id":f"dead-swamp-{index}","owner_id":"player","controller_id":"player","tapped":False,"damage":0,"counters":{},"summoning_sick":False} for index in range(4)];dead=[{**card(6544+index,f"Miracle Dead {index}","Creature — Zombie","{2}","2","2"),"instance_id":f"miracle-dead-{index}","owner_id":"player","controller_id":"player"} for index in range(2)];spell={**card(6546,"Entreat the Dead","Sorcery","{X}{X}{B}{B}{B}"),"oracle_text":"Return X target creature cards from your graveyard to the battlefield.\nMiracle {X}{B}{B}","instance_id":"entreat-dead","owner_id":"player","controller_id":"player"};player["battlefield"]=lands;player["graveyard"]=dead;player["library"].append(spell);_draw(state,player,1);action=next(entry for entry in legal_actions(state,"player") if entry["type"]=="cast_miracle");assert len(action["target_steps_by_x"][2])==2;state=perform_action(state,"player",{**action,"x_value":2,"target_ids":[entry["instance_id"] for entry in dead]});state=perform_action(state,"player",{"type":"resolve"});player=next(entry for entry in state["players"] if entry["id"]=="player");assert len([entry for entry in player["battlefield"] if entry["instance_id"].startswith("miracle-dead-")])==2


def test_miracle_global_zone_effects_resolve_to_the_correct_destinations():
    state=kept_game();player=next(entry for entry in state["players"] if entry["id"]=="player");bot=next(entry for entry in state["players"] if entry["id"]=="bot");player_creature={**card(6550,"Tide Ally","Creature — Human","{2}","2","2"),"instance_id":"tide-ally","owner_id":"player","controller_id":"player","tapped":False,"damage":0,"counters":{},"summoning_sick":False};bot_artifact={**card(6551,"Tide Relic","Artifact","{2}"),"instance_id":"tide-relic","owner_id":"bot","controller_id":"bot","tapped":False,"damage":0,"counters":{},"summoning_sick":False};land={**card(6552,"Tide Land","Basic Land — Island"),"instance_id":"tide-land","owner_id":"bot","controller_id":"bot","tapped":False,"damage":0,"counters":{},"summoning_sick":False};player["battlefield"]=[player_creature];bot["battlefield"]=[bot_artifact,land];tide={**card(6553,"Devastation Tide","Sorcery","{3}{U}{U}"),"oracle_text":"Return all nonland permanents to their owners' hands.\nMiracle {1}{U}","instance_id":"devastation-tide","owner_id":"player","controller_id":"player"};state["stack"]=[{"id":"tide-stack","kind":"spell","card":tide,"controller_id":"player","target_id":None,"target_ids":[],"mode_indices":[],"mode_targets":[],"x_value":0}];state=perform_action(state,"player",{"type":"resolve"});player=next(entry for entry in state["players"] if entry["id"]=="player");bot=next(entry for entry in state["players"] if entry["id"]=="bot");assert any(entry["instance_id"]=="tide-ally" for entry in player["hand"]) and any(entry["instance_id"]=="tide-relic" for entry in bot["hand"]) and [entry["instance_id"] for entry in bot["battlefield"]]==["tide-land"]
    creatures=[{**card(6554+index,f"Terminus Victim {index}","Creature — Beast","{2}","2","2"),"instance_id":f"terminus-victim-{index}","owner_id":owner_id,"controller_id":owner_id,"tapped":False,"damage":0,"counters":{},"summoning_sick":False} for index,owner_id in enumerate(("player","bot"))];player["battlefield"]=[creatures[0]];bot["battlefield"]=[land,creatures[1]];terminus={**card(6556,"Terminus","Sorcery","{4}{W}{W}"),"oracle_text":"Put all creatures on the bottom of their owners' libraries.\nMiracle {W}","instance_id":"terminus","owner_id":"player","controller_id":"player"};state["stack"]=[{"id":"terminus-stack","kind":"spell","card":terminus,"controller_id":"player","target_id":None,"target_ids":[],"mode_indices":[],"mode_targets":[],"x_value":0}];state=perform_action(state,"player",{"type":"resolve"});assert next(entry for entry in state["players"] if entry["id"]=="player")["library"][0]["instance_id"]=="terminus-victim-0" and next(entry for entry in state["players"] if entry["id"]=="bot")["library"][0]["instance_id"]=="terminus-victim-1"


def test_miracle_bonfire_and_temporal_mastery_apply_their_full_effects():
    state=kept_game();player=next(entry for entry in state["players"] if entry["id"]=="player");bot=next(entry for entry in state["players"] if entry["id"]=="bot");victim={**card(6560,"Bonfire Victim","Creature — Soldier","{2}","2","2"),"instance_id":"bonfire-victim","owner_id":"bot","controller_id":"bot","tapped":False,"damage":0,"counters":{},"summoning_sick":False};bot["battlefield"]=[victim];bonfire={**card(6561,"Bonfire of the Damned","Sorcery","{X}{X}{R}"),"oracle_text":"Bonfire of the Damned deals X damage to target player or planeswalker and each creature that player or that planeswalker's controller controls.\nMiracle {X}{R}","instance_id":"bonfire","owner_id":"player","controller_id":"player"};state["stack"]=[{"id":"bonfire-stack","kind":"spell","card":bonfire,"controller_id":"player","target_id":"bot","target_ids":[],"mode_indices":[],"mode_targets":[],"x_value":2}];state=perform_action(state,"player",{"type":"resolve"});assert next(entry for entry in state["players"] if entry["id"]=="bot")["life"]==18 and not next(entry for entry in state["players"] if entry["id"]=="bot")["battlefield"]
    mastery={**card(6562,"Temporal Mastery","Sorcery","{5}{U}{U}"),"oracle_text":"Take an extra turn after this one. Exile Temporal Mastery.\nMiracle {1}{U}","instance_id":"temporal-mastery","owner_id":"player","controller_id":"player"};state["stack"]=[{"id":"mastery-stack","kind":"spell","card":mastery,"controller_id":"player","target_id":None,"target_ids":[],"mode_indices":[],"mode_targets":[],"x_value":0}];state=perform_action(state,"player",{"type":"resolve"});player=next(entry for entry in state["players"] if entry["id"]=="player");assert state["extra_turns"]==["player"] and any(entry["instance_id"]=="temporal-mastery" for entry in player["exile"]) and not any(entry["instance_id"]=="temporal-mastery" for entry in player["graveyard"])


def test_disturb_auras_grant_visible_combat_triggers_and_dorothea_sacrifices_at_end_of_combat():
    state=kept_game();state["phase"]="combat";player=next(entry for entry in state["players"] if entry["id"]=="player");bot=next(entry for entry in state["players"] if entry["id"]=="bot");attacker={**card(6000,"Aura-Blessed Attacker","Creature — Spirit","{3}","3","3"),"instance_id":"aura-attacker","owner_id":"player","controller_id":"player","tapped":True,"damage":0,"counters":{},"summoning_sick":False,"attachment_rules":{"catlike":"Whenever this creature deals combat damage to a player, draw a card.","dorothea":"Whenever this creature attacks, create a 4/4 white Spirit creature token with flying that's tapped and attacking. Sacrifice that token at end of combat."}};victim={**card(6001,"Defending Target","Creature — Soldier","{2}","2","2"),"instance_id":"defending-target","owner_id":"bot","controller_id":"bot","tapped":False,"damage":0,"counters":{},"summoning_sick":False};bot["battlefield"]=[victim];player["battlefield"]=[attacker];state["combat"]["attackers"]=["aura-attacker"];state["combat"]["attack_targets"]={"aura-attacker":"bot"};_queue_triggers(state,"attackers_declared",None,player,sources_override=[(player,attacker)]);assert state["stack"] and "create a 4/4" in state["stack"][-1]["card"]["oracle_text"].casefold();state=perform_action(state,"player",{"type":"resolve"});player=next(entry for entry in state["players"] if entry["id"]=="player");token=next(entry for entry in player["battlefield"] if entry.get("token"));assert token["instance_id"] in state["combat"]["attackers"] and token["sacrifice_end_combat"]
    hand_before=len(player["hand"]);_combat_damage(state);player=next(entry for entry in state["players"] if entry["id"]=="player");assert len(player["hand"])==hand_before and len(state["stack"])==2;draw_trigger=next(item for item in state["stack"] if "draw a card" in item["card"]["oracle_text"].casefold());state["stack"].remove(draw_trigger);state["stack"].append(draw_trigger);state=perform_action(state,"player",{"type":"resolve"});player=next(entry for entry in state["players"] if entry["id"]=="player");assert len(player["hand"])==hand_before+1 and any(item["kind"]=="end_combat_sacrifice_trigger" for item in state["stack"]);state=perform_action(state,"player",{"type":"resolve"});player=next(entry for entry in state["players"] if entry["id"]=="player");assert not any(entry["instance_id"]==token["instance_id"] for entry in player["battlefield"])


def test_distracting_geist_granted_trigger_targets_only_the_assigned_defenders_creatures():
    state=kept_game();state["phase"]="combat";player=next(entry for entry in state["players"] if entry["id"]=="player");bot=next(entry for entry in state["players"] if entry["id"]=="bot");attacker={**card(6020,"Distracting Attacker","Creature — Spirit","{2}","2","2"),"instance_id":"distracting-attacker","owner_id":"player","controller_id":"player","tapped":True,"damage":0,"counters":{},"summoning_sick":False,"attachment_rules":{"distraction":"Whenever this creature attacks, tap target creature defending player controls."}};victim={**card(6021,"Distracted Creature","Creature — Soldier","{2}","2","2"),"instance_id":"distracted-creature","owner_id":"bot","controller_id":"bot","tapped":False,"damage":0,"counters":{},"summoning_sick":False};own={**card(6022,"Own Creature","Creature — Soldier","{2}","2","2"),"instance_id":"own-distraction-creature","owner_id":"player","controller_id":"player","tapped":False,"damage":0,"counters":{},"summoning_sick":False};player["battlefield"]=[attacker,own];bot["battlefield"]=[victim];state["combat"]["attackers"]=["distracting-attacker"];state["combat"]["attack_targets"]={"distracting-attacker":"bot"};_queue_triggers(state,"attackers_declared",None,player,sources_override=[(player,attacker)]);action=next(entry for entry in legal_actions(state,"player") if entry["type"]=="choose_trigger_target");assert [target["id"] for target in action["targets"]]==["distracted-creature"];state=perform_action(state,"player",{"type":"choose_trigger_target","target_id":"distracted-creature"});state=perform_action(state,"player",{"type":"resolve"});assert next(entry for entry in next(owner for owner in state["players"] if owner["id"]=="bot")["battlefield"] if entry["instance_id"]=="distracted-creature")["tapped"]


def test_departed_soulkeeper_blocks_only_fliers_and_gutter_shortcut_requires_a_solo_attacker():
    state=kept_game();player=next(owner for owner in state["players"] if owner["id"]=="player");bot=next(owner for owner in state["players"] if owner["id"]=="bot");solo={**card(6040,"Shortcut Bear","Creature — Bear","{2}","2","2"),"instance_id":"shortcut-bear","owner_id":"player","controller_id":"player","attachment_rules":{"shortcut":"Enchant creature\nEnchanted creature gets +2/+0 and can't be blocked as long as it’s attacking alone."}};ally={**card(6041,"Attack Ally","Creature — Spirit","{1}","1","1"),"instance_id":"attack-ally","owner_id":"player","controller_id":"player"};soulkeeper={**card(6042,"Departed Soulkeeper","Creature — Spirit Soldier","","3","3"),"oracle_text":"Flying\nThis creature can block only creatures with flying.","keywords":["Flying"],"instance_id":"departed-soulkeeper","owner_id":"bot","controller_id":"bot"};normal={**card(6043,"Ordinary Blocker","Creature — Human","{2}","2","2"),"instance_id":"ordinary-blocker","owner_id":"bot","controller_id":"bot"};flier={**card(6044,"Flying Spirit","Creature — Spirit","{2}","2","2"),"keywords":["Flying"],"instance_id":"flying-spirit","owner_id":"player","controller_id":"player"};player["battlefield"]=[solo,ally,flier];bot["battlefield"]=[soulkeeper,normal];state["combat"]["attackers"]=["shortcut-bear"];assert not _can_block_pair(state,solo,normal);state["combat"]["attackers"]=["shortcut-bear","attack-ally"];assert _can_block_pair(state,solo,normal) and not _can_block_pair(state,solo,soulkeeper) and _can_block_pair(state,flier,soulkeeper)


