    state=kept_game();player=next(owner for owner in state["players"] if owner["id"]=="player");bot=next(owner for owner in state["players"] if owner["id"]=="bot");shield={**card(6060,"Chapel Shieldgeist","Creature — Spirit Cleric","","2","1"),"oracle_text":"Flying, first strike\nEach creature you control has ward {1}.","instance_id":"chapel-shieldgeist","owner_id":"player","controller_id":"player"};ally={**card(6061,"Shielded Ally","Creature — Human","{2}","2","2"),"instance_id":"shielded-ally","owner_id":"player","controller_id":"player"};spell={**card(6062,"Hostile Spell","Instant","{B}"),"oracle_text":"Destroy target creature.","instance_id":"hostile-spell","owner_id":"bot","controller_id":"bot"};player["battlefield"]=[shield,ally];stack_item={"id":"hostile-stack","kind":"spell","card":spell,"controller_id":"bot","target_id":"shielded-ally"};state["stack"]=[stack_item];game_engine._queue_ward(state,bot,"shielded-ally",stack_item);assert state["pending_ward"]["mana_cost"]=="{1}" and state["pending_ward"]["source_name"]=="Shielded Ally"


