def test_benevolent_geist_keeps_noncreature_spells_on_the_stack_through_counter_attempts():
    for counter_text in ("Counter target spell.","Counter target spell unless its controller pays {3}."):
        state=kept_game();player=next(owner for owner in state["players"] if owner["id"]=="player");geist={**card(6100,"Benevolent Geist","Creature — Spirit Wizard","","2","2"),"oracle_text":"Flying\nNoncreature spells you control can't be countered.","instance_id":"benevolent-geist","owner_id":"player","controller_id":"player"};protected={**card(6101,"Protected Insight","Sorcery","{2}{U}"),"oracle_text":"Draw a card.","instance_id":"protected-insight","owner_id":"player","controller_id":"player"};counter={**card(6102,"Counter Attempt","Instant","{U}{U}"),"oracle_text":counter_text,"instance_id":"counter-attempt","owner_id":"bot","controller_id":"bot"};player["battlefield"]=[geist];state["stack"]=[{"id":"protected-stack","kind":"spell","card":protected,"controller_id":"player"},{"id":"counter-stack","kind":"spell","card":counter,"controller_id":"bot","target_id":"protected-stack"}];state=perform_action(state,"player",{"type":"resolve"});assert [item["id"] for item in state["stack"]]==["protected-stack"] and not state.get("pending_counter_payment") and any("can't be countered" in entry["message"] for entry in state["log"])


