    aura={**card(6121,"Friendly Aura","Enchantment — Aura","{W}"),"oracle_text":"Enchant creature\nEnchanted creature gets +1/+1.","instance_id":"friendly-aura","owner_id":"player","controller_id":"player"};aura_stack={"id":"friendly-aura-stack","kind":"spell","card":aura,"controller_id":"player","target_id":"brine-comber"};state["stack"]=[aura_stack];game_engine._queue_ward(state,player,"brine-comber",aura_stack);assert len(state["stack"])==2;state=perform_action(state,"player",{"type":"resolve"});player=next(owner for owner in state["players"] if owner["id"]=="player");assert len([permanent for permanent in player["battlefield"] if permanent.get("token")])==2
