def test_cosmium_catalyst_reveals_its_random_card_and_pauses_for_cast_or_decline():
    for cast_selected in (True,False):
        state=kept_game();state["phase"]="precombat_main";player=next(owner for owner in state["players"] if owner["id"]=="player")
        spell={**card(6790,"Catalyst Inspiration","Sorcery","{3}{R}"),"oracle_text":"Draw two cards.","instance_id":"catalyst-inspiration","owner_id":"player","controller_id":"player"};catalyst={**card(6791,"Cosmium Catalyst","Artifact"),"oracle_text":"{1}{R}, {T}: Choose an exiled card used to craft Cosmium Catalyst at random. You may cast that card without paying its mana cost.","crafted_with_ids":["catalyst-inspiration"],"crafted_with_cards":[spell],"instance_id":"cosmium-catalyst","owner_id":"player","controller_id":"player","tapped":False,"damage":0,"counters":{},"summoning_sick":False};lands=[{**card(6792+index,f"Catalyst Mountain {index}","Basic Land — Mountain"),"instance_id":f"catalyst-mountain-{index}","owner_id":"player","controller_id":"player","tapped":False,"damage":0,"counters":{}} for index in range(2)]
        player["battlefield"]=[catalyst,*lands];player["exile"].append(spell);action=next(action for action in legal_actions(state,"player") if action.get("card_id")=="cosmium-catalyst" and action["type"]=="activate");state=perform_action(state,"player",action);state=perform_action(state,"player",{"type":"resolve"});choices={action["type"] for action in legal_actions(state,"player")};assert choices>={"cast_catalyst","decline_catalyst"} and state["pending_catalyst"]["card_id"]=="catalyst-inspiration"
        if cast_selected:
            hand_size=len(player["hand"]);state=perform_action(state,"player",{"type":"cast_catalyst"});assert state["stack"][-1]["card"]["instance_id"]=="catalyst-inspiration" and state["stack"][-1]["free_cast"];state=perform_action(state,"player",{"type":"resolve"});player=next(owner for owner in state["players"] if owner["id"]=="player");assert len(player["hand"])==hand_size+2 and any(card["instance_id"]=="catalyst-inspiration" for card in player["graveyard"])
        else:
            state=perform_action(state,"player",{"type":"decline_catalyst"});player=next(owner for owner in state["players"] if owner["id"]=="player");assert any(card["instance_id"]=="catalyst-inspiration" for card in player["exile"]) and not state.get("pending_catalyst")


def test_apex_observatory_pauses_for_shared_type_then_makes_only_the_next_matching_spell_free():
    state=kept_game();state["phase"]="precombat_main";player=next(owner for owner in state["players"] if owner["id"]=="player");materials=[card(6800,"Bronze Beast","Artifact Creature — Beast","{3}","3","3"),card(6801,"Silver Bird","Artifact Creature — Bird","{2}","2","2")]
    observatory={**card(6802,"Apex Observatory","Artifact"),"oracle_text":"Apex Observatory enters tapped. As it enters, choose a card type shared among two exiled cards used to craft it.\n{T}: The next spell you cast this turn of the chosen type can be cast without paying its mana cost.","crafted_with_cards":materials,"crafted_with_ids":["bronze-beast","silver-bird"],"instance_id":"apex-observatory","owner_id":"player","controller_id":"player","tapped":False,"damage":0,"counters":{},"summoning_sick":False};_enter_battlefield(state,player,[observatory],"exile");choice=next(action for action in legal_actions(state,"player") if action["type"]=="choose_card_type");assert choice["card_types"]==["Artifact","Creature"];state=perform_action(state,"player",{"type":"choose_card_type","card_type":"Creature"});player=next(owner for owner in state["players"] if owner["id"]=="player");observatory=next(permanent for permanent in player["battlefield"] if permanent["instance_id"]=="apex-observatory");assert observatory["tapped"] and observatory["chosen_card_type"]=="Creature"
    observatory["tapped"]=False;action=next(action for action in legal_actions(state,"player") if action.get("card_id")=="apex-observatory" and action["type"]=="activate");state=perform_action(state,"player",action);state=perform_action(state,"player",{"type":"resolve"});player=next(owner for owner in state["players"] if owner["id"]=="player");expensive={**card(6803,"Apex Behemoth","Creature — Beast","{8}","8","8"),"instance_id":"apex-behemoth","owner_id":"player","controller_id":"player"};player["hand"].append(expensive);cast_action=next(action for action in legal_actions(state,"player") if action.get("card_id")=="apex-behemoth" and action["type"]=="cast");assert cast_action["apex_free"] and "without paying" in cast_action["label"];state=perform_action(state,"player",cast_action);player=next(owner for owner in state["players"] if owner["id"]=="player");assert not player.get("apex_free_spell_type") and state["stack"][-1]["card"]["instance_id"]=="apex-behemoth"


def test_sandswirl_wanderglyph_enforces_cast_or_attack_but_not_both():
    state=kept_game();state["active_player_id"]=state["priority_player_id"]="bot";state["phase"]="precombat_main";controller=next(owner for owner in state["players"] if owner["id"]=="player");actor=next(owner for owner in state["players"] if owner["id"]=="bot");glyph={**card(6810,"Sandswirl Wanderglyph","Artifact Creature — Golem","","5","3"),"oracle_text":"Flying\nWhenever an opponent casts a spell during their turn, they can't attack you or planeswalkers you control this turn.\nEach opponent who attacked you or a planeswalker you control this turn can't cast spells.","instance_id":"sandswirl-wanderglyph","owner_id":"player","controller_id":"player","tapped":False,"damage":0,"counters":{},"summoning_sick":False};controller["battlefield"]=[glyph];spell={**card(6811,"Early Spark","Sorcery","{0}"),"instance_id":"early-spark","owner_id":"bot","controller_id":"bot"};_queue_triggers(state,"cast",spell,actor,sources_override=[(controller,glyph)]);assert state["stack"] and "can't attack" in state["stack"][-1]["card"]["oracle_text"].casefold();game_engine._resolve_spell(state);state["phase"]="combat";assert not any(action["type"]=="declare_attackers" for action in legal_actions(state,"bot"))
    state=kept_game();state["active_player_id"]=state["priority_player_id"]="bot";state["phase"]="combat";controller=next(owner for owner in state["players"] if owner["id"]=="player");actor=next(owner for owner in state["players"] if owner["id"]=="bot");controller["battlefield"]=[{**glyph,"tapped":False}];attacker={**card(6812,"Glyph Raider","Creature — Pirate","","2","2"),"instance_id":"glyph-raider","owner_id":"bot","controller_id":"bot","tapped":False,"damage":0,"counters":{},"summoning_sick":False};actor["battlefield"]=[attacker];declare=next(action for action in legal_actions(state,"bot") if action["type"]=="declare_attackers");state=perform_action(state,"bot",{"type":"declare_attackers","attacker_ids":["glyph-raider"],"attack_targets":{"glyph-raider":"player"}});state["phase"]="postcombat_main";state["combat"]={"attackers":[],"attackers_declared":False,"blocks":{},"attack_targets":{},"block_orders":{},"damage_pending":False,"damage_step":None,"first_strike_damage_ids":[],"block_triggers_pending":False};actor=next(owner for owner in state["players"] if owner["id"]=="bot");actor["hand"].append({**card(6813,"Late Spark","Sorcery","{0}"),"instance_id":"late-spark","owner_id":"bot","controller_id":"bot"});assert not any(action["type"].startswith("cast") for action in legal_actions(state,"bot"))


def test_dinosaur_headdress_pauses_on_every_attachment_and_restores_each_creature():
    state=kept_game();player=next(owner for owner in state["players"] if owner["id"]=="player");dragon={**card(6820,"Craft Dragon","Creature — Dragon","{4}{R}","5","5"),"oracle_text":"Flying","keywords":["Flying"],"instance_id":"craft-dragon"};merfolk={**card(6821,"Craft Merfolk","Creature — Merfolk","{1}{U}","2","2"),"oracle_text":"Vigilance","keywords":["Vigilance"],"instance_id":"craft-merfolk"};equipment={**card(6822,"Dinosaur Headdress","Artifact — Equipment"),"oracle_text":"When this Equipment enters, attach it to target creature you control.\nAs this Equipment becomes attached to a creature, choose an exiled creature card used to craft this Equipment.\nEquipped creature is a copy of the last chosen card.\nEquip {2}","crafted_with_cards":[dragon,merfolk],"instance_id":"dinosaur-headdress","owner_id":"player","controller_id":"player","tapped":False,"damage":0,"counters":{}};bearers=[{**card(6823+index,f"Headdress Bearer {index}","Creature — Human","{1}",str(index+1),str(index+2)),"instance_id":f"headdress-bearer-{index}","owner_id":"player","controller_id":"player","tapped":False,"damage":0,"counters":{},"summoning_sick":False} for index in range(2)];player["battlefield"]=[equipment,*bearers]
    game_engine._attach(state,equipment,bearers[0]);choice=next(action for action in legal_actions(state,"player") if action["type"]=="choose_headdress_card");assert {card["name"] for card in choice["cards"]}=={"Craft Dragon","Craft Merfolk"};state=perform_action(state,"player",{"type":"choose_headdress_card","card_id":"craft-dragon"});player=next(owner for owner in state["players"] if owner["id"]=="player");equipment=next(card for card in player["battlefield"] if card["instance_id"]=="dinosaur-headdress");first=next(card for card in player["battlefield"] if card["instance_id"]=="headdress-bearer-0");second=next(card for card in player["battlefield"] if card["instance_id"]=="headdress-bearer-1");assert first["name"]=="Craft Dragon" and _parse_stats(first,state)==(5,5) and _has_keyword(first,"Flying")
    game_engine._attach(state,equipment,second);assert first["name"]=="Headdress Bearer 0" and _parse_stats(first,state)==(1,2);state=perform_action(state,"player",{"type":"choose_headdress_card","card_id":"craft-merfolk"});player=next(owner for owner in state["players"] if owner["id"]=="player");equipment=next(card for card in player["battlefield"] if card["instance_id"]=="dinosaur-headdress");second=next(card for card in player["battlefield"] if card["instance_id"]=="headdress-bearer-1");assert second["name"]=="Craft Merfolk" and _parse_stats(second,state)==(2,2);game_engine._detach(state,equipment);assert second["name"]=="Headdress Bearer 1" and _parse_stats(second,state)==(2,3)


def test_grim_captain_stages_opponent_sacrifice_then_optional_crafted_attacker():
    state=kept_game();state["phase"]="combat";player=next(owner for owner in state["players"] if owner["id"]=="player");bot=next(owner for owner in state["players"] if owner["id"]=="bot");material={**card(6830,"Crafted Raptor","Creature — Dinosaur","{3}{G}","4","4"),"instance_id":"crafted-raptor","owner_id":"player","controller_id":"player"};captain={**card(6831,"The Grim Captain","Legendary Creature — Skeleton Spirit Pirate","","7","7"),"oracle_text":"Menace, trample, lifelink, hexproof\nWhenever The Grim Captain attacks, each opponent sacrifices a nonland permanent. Then you may put an exiled creature card used to craft The Grim Captain onto the battlefield under your control tapped and attacking.","crafted_with_ids":["crafted-raptor"],"crafted_with_cards":[material],"instance_id":"grim-captain","owner_id":"player","controller_id":"player","tapped":True,"damage":0,"counters":{},"summoning_sick":False};tribute={**card(6832,"Captain Tribute","Artifact"),"instance_id":"captain-tribute","owner_id":"bot","controller_id":"bot","tapped":False,"damage":0,"counters":{}};player["battlefield"]=[captain];player["exile"].append(material);bot["battlefield"]=[tribute];state["combat"]["attackers"]=["grim-captain"];state["combat"]["attack_targets"]={"grim-captain":"bot"};_queue_triggers(state,"attackers_declared",None,player,sources_override=[(player,captain)]);assert state["stack"];game_engine._resolve_spell(state);sacrifice=next(action for action in legal_actions(state,"bot") if action["type"]=="choose_grim_sacrifice");assert sacrifice["card_ids"]==["captain-tribute"];state=perform_action(state,"bot",{"type":"choose_grim_sacrifice","card_id":"captain-tribute"});returned=next(action for action in legal_actions(state,"player") if action["type"]=="choose_grim_return");assert returned["card_ids"]==["crafted-raptor"] and any(target["id"]=="bot" for target in returned["defenders"]);state=perform_action(state,"player",{"type":"choose_grim_return","card_id":"crafted-raptor","target_id":"bot"});player=next(owner for owner in state["players"] if owner["id"]=="player");raptor=next(card for card in player["battlefield"] if card["instance_id"]=="crafted-raptor");assert raptor["tapped"] and "crafted-raptor" in state["combat"]["attackers"] and state["combat"]["attack_targets"]["crafted-raptor"]=="bot" and not state.get("pending_grim_captain")
